INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7445', 'spa', 'grito de jubilo, clamor gozoso, exultacion', 'Este sustantivo designa gritos resonantes de alegria o jubilo, ya sea en contextos de adoracion, celebracion o, ironicamente, el breve triunfo de los malvados. Emparentado con el verbo ''cantar de gozo'', enfatiza la exuberancia vocal y la jubilacion. El termino aparece tanto en contextos positivos de adoracion como en descripciones negativas de un placer efimero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7448', 'spa', 'brida, freno, cabestro (sujecion para animales)', 'Este sustantivo designa principalmente una brida o cabestro para sujetar caballos o mulos, y posiblemente tambien la quijada que controla. Se usa literalmente para el control de animales y metaforicamente para la restriccion divina sobre las naciones o la rebeldia humana. El termino aparece en contextos sapienciales, profeticos y poeticos, enfatizando el control y la sumision.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7451', 'spa', 'El mal; la cosa o conducta moralmente perversa que debe ser purgada de la comunidad. En esta forma particular —el adjetivo רַע con el artículo definid', 'El mal; la cosa o conducta moralmente perversa que debe ser purgada de la comunidad. En esta forma particular —el adjetivo רַע con el artículo definido— la expresión funciona casi como una fórmula legal técnica en la ley del pacto de Deuteronomio: ''quitarás el mal de en medio de ti'' (Dt 17:12; 19:19; 21:21; 22:21–22, 24). No designa meramente una cualidad negativa, sino el acto malvado concreto o la persona que contamina la comunidad del pacto y debe ser eliminada para mantener la santidad. La fórmula reaparece con fuerza judicial, señalando delitos que conllevan pena de muerte: rebelión contra la autoridad sacerdotal, falso testimonio, transgresión sexual y secuestro. El artículo definido eleva el adjetivo a sustantivo —''el mal (la cosa mala)''— confiriéndole un peso casi nominal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7451a', 'spa', 'Malo, malvado; abarcando corrupción moral, calamidad dañina, mala calidad, fealdad, gravedad feroz y semblante triste.', 'El adjetivo רַע es una de las palabras con mayor carga teológica de la Biblia hebrea, presente en el diagnóstico mismo de la caída humana: ''todo designio de los pensamientos del corazón del hombre era solo mal continuamente'' (Gn 6:5). Sin embargo, su alcance va mucho más allá de la ética. Las vacas flacas de Faraón son רָעוֹת — feas, no pecadoras (Gn 41:3). Una ''enfermedad רָעָה'' es maligna, no inmoral (Dt 28:35). El ''semblante רַע'' de Nehemías es simplemente triste (Neh 2:2). El árabe distribuye estos sentidos entre شَرّ (mal moral), قَبِيح (feo), شَدِيد (severo) y حَزِين (triste), exponiendo la notable compresión semántica que el hebreo logra con un solo adjetivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7451b', 'spa', 'Mal, maldad, calamidad, daño, angustia: abarca maldad moral, deficiencia cualitativa, infortunio y perjuicio intencional.', 'רַע como sustantivo es el gran antónimo de טוֹב (''bien'') en el vocabulario moral hebreo, pero su alcance se extiende mucho más allá de la ética. Nombra el ''mal'' del árbol del conocimiento (Gn 2:9), la ''calamidad'' que Dios crea junto con la paz (Is 45:7), la ''adversidad'' de los tiempos difíciles (Sal 49:5) y el ''daño'' que una persona inflige a otra (Jer 7:6). Esta amplitud es teológicamente significativa: el hebreo no compartimenta maldad moral, desastre natural y sufrimiento vivido en lexemas separados como hacen muchas lenguas modernas. El árabe شَرّ abarca igualmente maldad y desgracia, mientras que el alemán distingue Böses (moral) de Unheil (calamidad) y el coreano separa 악 (mal moral) de 재앙 (desastre) y 해 (daño).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7451c', 'spa', 'Maldad, calamidad, daño, angustia: sustantivo femenino que abarca perversidad moral, desastre, perjuicio y sufrimiento.', 'Un sustantivo femenino que cubre todo el espectro de lo malo en el mundo bíblico, desde la maldad moral hasta el juicio divino y el sufrimiento personal. Cuando se asocia con un posesor (''la maldad de vuestras obras''), denota carácter o intención pecaminosa; cuando Dios ''trae רָעָה'' sobre una nación, se desplaza hacia la calamidad o la ruina. La evidencia multilingüe es reveladora: el español distingue ''mal'' (maldad/daño) de ''calamidad'' (desastre), y el alemán separa ''Böses'' (mal moral) de ''Unheil'' (catástrofe) y ''Trübsal'' (tribulación), confirmando que el hebreo רָעָה genuinamente abarca estos territorios semánticos distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7452', 'spa', 'grito, clamor fuerte; rugido (posiblemente trueno)', 'Este sustantivo describe sonido vocal fuerte—ya sea griterío humano o posiblemente el rugido del trueno. La palabra aparece en contextos de conmoción y ruido, aunque dificultades textuales hacen inciertas algunas instancias. Éxodo puede referirse al sonido de gente gritando, Miqueas al clamor fuerte de angustia, y Job posiblemente al rugido del trueno anunciando la presencia de Dios, aunque existen lecturas alternativas para varios pasajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7453', 'spa', 'Amigo, compañero, prójimo, semejante; persona vinculada por proximidad, afecto o actividad compartida.', 'רֵעַ es uno de los sustantivos con mayor carga social de la Biblia hebrea, abarcando toda la gama de la conexión interpersonal. En los códigos legales de Éxodo y Deuteronomio significa ''prójimo'': la persona a tu lado a quien no debes robar ni envidiar (Éx 20:17; Lv 19:18). Pero en la narrativa, la misma palabra describe amistad profunda: Husai es el רֵעַ de David (2 S 15:37), y Moisés habla con Dios ''como habla un hombre con su amigo'' (Éx 33:11). El árabe separa جَار (vecino), صَدِيق (amigo) y صَاحِب (asociado); el hebreo mantiene los tres bajo una sola palabra. Esta compresión es teológicamente significativa: aquel a quien se te ordena amar es a la vez prójimo, compañero y amigo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7455', 'spa', 'Maldad, perversidad, mal moral (especialmente de las obras humanas); tristeza del rostro o el corazón; mala calidad o fealdad.', 'Maldad, perversidad, mal moral (especialmente de las obras humanas); tristeza del rostro o el corazón; mala calidad o fealdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7456', 'spa', 'Tener hambre, pasar hambre (Qal intransitivo); causar hambre, hacer pasar hambre (Hifil causativo). רָעֵב (ra''ev) es el verbo principal de la Biblia h', 'Tener hambre, pasar hambre (Qal intransitivo); causar hambre, hacer pasar hambre (Hifil causativo). רָעֵב (ra''ev) es el verbo principal de la Biblia hebrea para la experiencia visceral del hambre. En su forma Qal describe el estado de tener hambre —desde el Egipto de José donde ''toda la tierra padecía hambre'' (Gn 41:55) hasta la promesa de que quienes confían en el SEÑOR ''no carecerán de bien alguno'' mientras ''los leoncillos necesitan y tienen hambre'' (Sal 34:10). Isaías lo emplea en agudos contrastes: ''mis siervos comerán, pero vosotros tendréis hambre'' (Is 65:13). Proverbios observa que ''el apetito del perezoso pasa hambre'' (Pr 19:15) y que incluso se compadece al ladrón ''si roba para saciar su hambre'' (Pr 6:30). La menos frecuente forma Hifil invierte el sujeto: Dios ''te hizo pasar hambre'' en el desierto antes de alimentar a Israel con maná (Dt 8:3) —una privación formativa. El Hifil posee un filo teológico singular: Dios causa deliberadamente el hambre como pedagogía, lo que otorga al sentido causativo una profundidad que trasciende la mera fisiología.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7457', 'spa', 'Hambriento, famélico — describe a personas necesitadas de alimento, frecuentemente emparejado con ''sediento'' o ''agotado'' en contextos de justicia y mi', 'Hambriento, famélico — describe a personas necesitadas de alimento, frecuentemente emparejado con ''sediento'' o ''agotado'' en contextos de justicia y misericordia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7458', 'spa', 'Hambre, hambruna; escasez grave y generalizada de alimentos en una tierra, o la sensación física personal de tener hambre.', 'רָעָב aparece a lo largo de la narrativa veterotestamentaria como una de las grandes pruebas de la vida del pacto. Las hambrunas patriarcales (Gn 12:10; 26:1; 41:27-57) impulsan la trama de Génesis, y el hambre funciona como maldición del pacto junto con la espada y la pestilencia en los profetas (Jer 14:12; Ez 5:12). En su sentido menos frecuente pero importante de experiencia personal, רָעָב describe la sensación física punzante del hambre que sienten los individuos, como cuando Israel es disciplinado ''con hambre y con sed'' (Dt 28:48). El alemán distingue bien entre Hungersnot (hambruna como desastre nacional) y Hunger (hambre personal), distinción que la palabra hebrea porta dentro de un solo lexema.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7459', 'spa', 'hambre, hambruna, falta severa de alimento', 'Este sustantivo designa escasez seria de alimentos o condiciones de hambruna. Génesis lo usa para el hambre que afligía la casa de Jacob durante la hambruna egipcia, mientras que los Salmos lo emplean para contrastar la provisión justa con la escasez. El término enfatiza privación sostenida más que apetito momentáneo, representando falta de sustento que amenaza la vida y empuja a la gente a medidas desesperadas como migrar a Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7460', 'spa', 'temblar, estremecerse (de miedo o temor reverente)', 'Este verbo describe temblar o estremecerse, típicamente por miedo, reverencia o presencia divina. La tierra tiembla ante la mirada de Dios en imágenes teofánicas. Daniel se queda temblando después de un encuentro angelical. Esdras describe a los residentes de Jerusalén sentados y temblando bajo la lluvia, abrumados por la conciencia del pecado. El temblor puede ser físico o emocional, pero consistentemente indica respuesta a algo abrumador—presencia divina, revelación profética o crisis moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7461b', 'spa', 'temblor, estremecimiento temeroso', 'Este sustantivo femenino describe el temblor o estremecimiento que sobrecoge a las personas en temor o reverencia. Emparejado con palabras para miedo y terror, aparece en contextos de encuentro divino o amenaza abrumadora. Salmo 2 llama a servir a Dios ''con temblor''—temor reverente apropiado a Su majestad. Salmo 48 lo usa para el temblor que sobrecogió a reyes hostiles cuando vieron Jerusalén. Isaías describe a pecadores en Sion agarrados por temblor temeroso ante el fuego consumidor de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7462b', 'spa', 'Pastorear, apacentar o pacer rebaños; también el sustantivo agente ''pastor''; por extensión, pacer (intransitivo) o devorar en sentido figurado.', 'Pocas palabras hebreas portan tanta carga teológica como רָעָה. Desde el pastoreo literal de Abel en Génesis 4:2 hasta la declaración divina «Yo mismo apacentaré mis ovejas» en Ezequiel 34:15, este verbo tiende un puente entre el mundo cotidiano de la ganadería y la imagen exaltada de la realeza divina. El participio Qal רֹעֶה se convirtió en título estándar de los líderes de Israel —reyes-pastores cuyo fracaso llevó a Dios a asumir el cargo (Ez 34). El sentido intransitivo describe animales paciendo en la pradera, claramente marcado en español por pacer/pastar (frente al transitivo apacentar). Una rara extensión figurada convierte el pacer en devorar: «el jabalí la devora» (Sal 80:13), donde la imagen pastoril se invierte en destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7462c', 'spa', 'Asociarse con, acompañar; también pacer, alimentar, apacentar rebaños o tierra', 'Raíz secundaria רָעָה (II), distinta del verbo común de pastoreo, que porta el sentido social de compañerismo y asociación. En Proverbios aparece repetidamente como advertencia: ''el que se junta con necios'' (Prov 13:20), ''el que se asocia con glotones'' (28:7), ''el que anda con prostitutas'' (29:3). El español capta ambas dimensiones: ''te asocies'' (asociarse) frente a ''apacienta'' (apacentar/pacer), revelando cómo las tradiciones traductoras a veces confunden las dos raíces. El sentido pastoral emerge en Salmo 37:3 (''cultiva la fidelidad'') e Isaías 11:7, donde la vaca y el oso pacen juntos en la paz mesiánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7463', 'spa', 'amigo (titulo formal o companero intimo)', 'Este sustantivo designa a un amigo o companero, y aparece tanto como titulo tecnico (''el amigo del rey'', un cargo cortesano) como en sentido relacional sencillo. El termino representa una variante de la palabra mas comun para amigo, siendo su uso tecnico especialmente notable en contextos de la corte real, donde senala a un consejero de confianza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7466', 'spa', 'Reú — nombre patriarcal, hijo de Péleg en la línea de Sem a Abraham', 'Reú es un nombre propio que aparece en la genealogía de Sem a Abraham, identificado como hijo de Péleg y padre de Serug. Las cinco apariciones son estrictamente genealógicas: cuatro en Génesis 11:18-21 registran su nacimiento, su paternidad de Serug y los años de su vida, mientras que 1 Crónicas 1:25 repite su lugar en el linaje. El nombre se translitéra de manera uniforme en español como ''Reú'' y corresponde al griego Ραγαύ en la Septuaginta. Posiblemente derive de una raíz que significa ''amigo'' o ''compañero,'' conectándolo con la raíz hebrea más amplia רָעָה.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7467', 'spa', 'Reuel, ''amigo de Dios,'' nombre del suegro de Moisés, un ancestro edomita y otros personajes bíblicos', 'Nombre teofórico que significa ''amigo de Dios'' o ''compañero de El,'' portado por varios personajes a lo largo de las Escrituras. El más destacado es Reuel, sacerdote madianita y suegro de Moisés, quien acogió al pastor fugitivo y le dio a su hija Séfora como esposa (Éx 2:18). En las genealogías edomitas, Reuel aparece como hijo de Esaú y Basemat, padre de varios jefes de Edom (Gn 36:4, 10, 13, 17). El nombre también surge en las genealogías de Gad y Benjamín (Nm 10:29; 1 Cr 9:8), lo que atestigua su amplia circulación en el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7468', 'spa', 'Compañera, vecina, prójima; la contraparte femenina de rea (amigo/prójimo)', 'Forma femenina del sustantivo común rea (''amigo, prójimo''), que designa a la contraparte femenina, compañera o par de una mujer. En Éxodo 11:2, se dice a las mujeres israelitas que pidan ''cada una a su vecina'' plata y oro, haciendo eco de la instrucción masculina. Jeremías 9:20 lo usa en una elegía donde las mujeres enseñan a sus compañeras el lamento fúnebre. En Isaías 34:15-16, describe aves rapaces emparejándose con sus parejas en la desolación de Edom. Ester 1:19 lo emplea en un decreto legal: la posición real de Vasti será dada a otra mujer más digna que ella.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7469', 'spa', 're''ut — afán, anhelo o persecución; correr tras el viento (usado exclusivamente en Eclesiastés)', 'Sustantivo femenino que aparece únicamente en Eclesiastés, siempre en la expresión distintiva re''ut ruach («correr tras el viento» o «aflicción de espíritu»). Qohélet emplea esta frase como su veredicto característico sobre el esfuerzo humano: todo trabajo, búsqueda de sabiduría y persecución de placer equivalen en último término a intentar atrapar lo inatrapable. La palabra aparece siete veces (Ecl 1:14; 2:11, 17, 26; 4:4, 6; 6:9), siempre junto a hevel («vapor, vanidad»). Su etimología es discutida: posiblemente de ra''ah («apacentar») en el sentido de «deseo» o «afán», o de una raíz que significa «quebrar».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7473', 'spa', 'Pastor o ganadero; participio Qal de רָעָה usado para quienes apacientan rebaños, incluyendo a Dios y gobernantes', 'Participio activo del verbo ''pastorear'' empleado como sustantivo: el que alimenta y cuida rebaños. En sentido literal, describe a los ganaderos de las narraciones patriarcales, donde la disputa entre los pastores de Abram y Lot señala la necesidad de separarse (Gn 13:7-8). La palabra alcanza su cumbre teológica en el Salmo 23:1, ''El Señor es mi pastor,'' donde el cuidado íntimo del pastor por su rebaño se convierte en la metáfora definitiva de la relación de Dios con su pueblo. La literatura profética la extiende a gobernantes humanos, como cuando Dios llama a Ciro ''mi pastor'' (Is 44:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7474', 'spa', 'Compañera femenina o amada; término de tierno cariño usado casi exclusivamente en el Cantar de los Cantares para la novia.', 'Sustantivo tierno de tratamiento que significa ''compañera mía'' o ''amada mía'', reservado casi por completo para la mujer amada en el Cantar de los Cantares. El amante emplea esta palabra nueve veces para dirigirse a su novia con cálida intimidad, acompañándola de declaraciones de belleza y anhelo (''He aquí que eres hermosa, amada mía'', Cnt 1:15; 4:1). En español se traduce como ''amada mía'' y ''amiga mía'', abarcando tanto la dimensión romántica como la de compañerismo profundo. El francés ''ma bien-aimée'' y el alemán ''meine Freundin'' reflejan de modo semejante ese doble registro de amor apasionado y amistad entrañable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7475', 'spa', 'afán, búsqueda; preocupación, ocupación (de la mente)', 'Este sustantivo aparece exclusivamente en Eclesiastés, describiendo afán mental, búsqueda o ocupación ansiosa. A menudo emparejado con ''espíritu'' o ''viento'' en la frase ''afán tras el viento,'' captura la búsqueda frustrante de lo que no puede asirse. El término también describe la carga mental o preocupación que ocupa la mente en el trabajo—el esfuerzo cognitivo y emocional que acompaña la labor. Sugiere tanto alcance fútil de significado como el peso psicológico del esfuerzo humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7476', 'spa', 'Pensamiento, reflexión, cogitación — sustantivo arameo exclusivo de Daniel que denota actividad mental interior.', 'Sustantivo masculino arameo que significa ''pensamiento'' o ''reflexión'', presente únicamente en el libro de Daniel, siempre en plural. La palabra capta la vida interior de la mente: los pensamientos que surgen espontáneamente en el lecho (Dan 2:29), las cogitaciones que turban el espíritu de un rey (Dan 4:19; 5:6) y las interpretaciones que revelan lo que yace en el corazón (Dan 2:30). El propio Daniel la emplea para describir sus propias reflexiones turbadas tras la visión de las cuatro bestias (Dan 7:28). Este término otorga una textura introspectiva, casi psicológica, a las narraciones arameas de la corte, subrayando que solo Dios conoce y revela el pensamiento humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7481', 'spa', 'Tronar o rugir; verbo cuyo significado primario gira en torno al sonido profundo y resonante del trueno. En el Hifil, describe a Dios tronando desde e', 'Tronar o rugir; verbo cuyo significado primario gira en torno al sonido profundo y resonante del trueno. En el Hifil, describe a Dios tronando desde el cielo como acto de poder y juicio, como cuando el SEÑOR tronó contra los filisteos en Mizpa (1 Sam 7:10) o cuando la voz del SEÑOR truena sobre las aguas (Sal 29:3). En el Qal, el mar mismo es invitado a rugir y bramar en alabanza exuberante (Sal 96:11; 98:7). Un sentido extendido aparece en Ezequiel 27:35, donde los rostros de los espectadores ante la caída de Tiro se perturban o convulsionan, y en 1 Samuel 1:6 donde Penina provoca a Ana hasta hacerla temblar de angustia. Las traducciones al español y al francés (''tronó'', ''tonna'') preservan la imaginería onomatopéyica del trueno, mientras que ''se perturbaron'' capta la extensión emocional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7482', 'spa', 'Trueno; el poderoso estruendo atribuido al poder de Dios y a su autorrevelación teofánica.', 'Designa el profundo y reverberante rugido del trueno, atribuido de manera constante en la Biblia hebrea al poder soberano de Yahvé. En los Salmos, ''tu trueno estaba en el torbellino'' (Sal 77:18) y ''te respondí en el lugar secreto del trueno'' (Sal 81:7) vinculan directamente el trueno con el encuentro divino. Job 26:14 lo emplea figuradamente para referirse al mero borde susurrante del poder de Dios, mientras que Job 39:25 extiende la imagen al estruendoso grito de batalla de los comandantes. El término captura la fuerza acústica cruda de la manifestación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7484', 'spa', 'Raamá — descendiente de Cus y pueblo comerciante del sur de Arabia', 'Raamá aparece en la Tabla de las Naciones como ''hijo'' de Cus (Gn 10:7; 1 Cr 1:9), representando un pueblo o región del sur de Arabia. En Ezequiel 27:22, Raamá resurge como socio comercial de Tiro, traficando con especias, piedras preciosas y oro, lo que sitúa a este grupo de lleno en las rutas del incienso de la península arábiga. El nombre probablemente se conecta con un asentamiento cercano a Ma''in en el suroeste de Arabia. Las versiones en distintas lenguas son notablemente uniformes: español ''Raama/Raamá,'' francés ''Raamah/Raema,'' señalando una tradición de identificación bien establecida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7486', 'spa', 'Ramesés — ciudad y distrito egipcio en el delta oriental del Nilo, construida con trabajo forzado israelita', 'Ramesés designa tanto una ciudad como el distrito circundante en el delta oriental del Nilo, estrechamente vinculado con la narrativa del Éxodo. Nombrada en honor al faraón Ramsés II, aparece como ciudad de almacenaje construida mediante trabajo forzado israelita (Éx 1:11), como punto de partida del Éxodo (Éx 12:37; Nm 33:3, 5) y, con anterioridad, como la región donde José asentó a su familia (Gn 47:11). La evidencia multilingüe es notablemente estable: español ''Ramesés/Ramsés,'' francés ''Ramsès,'' alemán ''Ramses,'' todas reflejando el nombre real egipcio. La identificación arqueológica lo sitúa cerca de Tell el-Dab''a/Qantir en el delta oriental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7488b', 'spa', 'Frondoso, verde, exuberante; de árboles en pleno follaje, especialmente en sitios de culto idolátrico; figuradamente, fresco y vigoroso.', 'Frondoso, verde, exuberante; de árboles en pleno follaje, especialmente en sitios de culto idolátrico; figuradamente, fresco y vigoroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7489a', 'spa', 'Este verbo denominativo del adjetivo רַע (''malo, perverso'') abarca todo el espectro desde resultar desagradable hasta perpetrar daño activamente. En e', 'Este verbo denominativo del adjetivo רַע (''malo, perverso'') abarca todo el espectro desde resultar desagradable hasta perpetrar daño activamente. En el Qal describe un estado: algo «es malo a los ojos de alguien» — la angustia de Abraham por Ismael (Gn 21:11-12), o lo que «desagradó al SEÑOR» (Gn 38:10). El Hifil pasa a la acción volitiva: hacer el mal, tratar mal a alguien o causar daño, como cuando los egipcios maltrataron a Israel (Éx 5:23) o el salmista advierte contra irritarse por los malhechores (Sal 37:1). El participio Hifil se cristaliza en un sustantivo, «malhechor», término favorito en la literatura sapiencial y sálmica para quienes practican la maldad habitualmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7489b', 'spa', 'Quebrantar, destrozar, hacer pedazos; intransitivamente quebrarse o arruinarse', 'Verbo de rotura violenta, distinto del más común raʿaʿ I («ser malo»). Su fuerza es física y concreta: hierro que quiebra hierro (Jer 15:12), una vara de hierro que destroza naciones (Sal 2:9), Dios que quebranta a los poderosos sin indagación (Job 34:24). Las formas intransitivas Qal y Hitpael describen la tierra misma deshaciéndose en el temblor apocalíptico de Isaías 24:19. En Proverbios 18:24, el quebrantamiento se vuelve metafórico: tener demasiados compañeros conduce a la ruina propia. «Quebrantar» y «quebrarse» captan tanto la acción transitiva de destrozar como el colapso intransitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7491', 'spa', 'Gotear, destilar — del rocío, la lluvia o la bendición celestial cayendo suavemente desde lo alto', 'Verbo poético que evoca el descenso suave y continuo de la humedad desde el cielo hasta la tierra. Las nubes gotean lluvia sobre la gente (Job 36:28), los cielos destilan rocío (Prov 3:20) y las rodadas de Dios rebosan de abundancia mientras los pastizales del desierto gotean (Sal 65:11-12). Isaías 45:8 transforma la imagen física en mandato profético: «¡Destilad, cielos, desde lo alto!», donde la lluvia se convierte en metáfora de la justicia. La sinonimia con נָזַל y עָרַף confirma que se trata de un término de precipitación con fuerte potencial figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7493', 'spa', 'Temblar, estremecerse o sacudirse; en causativo, hacer temblar; también del grano que ondea o de un animal que salta', 'Temblar, estremecerse o sacudirse; en causativo, hacer temblar; también del grano que ondea o de un animal que salta');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7494', 'spa', 'Temblor, terremoto o estruendo atronador; desde eventos sísmicos hasta la sacudida violenta de la guerra y las teofanías divinas.', 'Temblor, terremoto o estruendo atronador; desde eventos sísmicos hasta la sacudida violenta de la guerra y las teofanías divinas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7495', 'spa', 'El verbo hebreo principal para sanar, que abarca la curación física, la restauración espiritual e incluso la reparación estructural. En el Qal, Dios d', 'El verbo hebreo principal para sanar, que abarca la curación física, la restauración espiritual e incluso la reparación estructural. En el Qal, Dios declara «Yo mato y yo doy vida; yo hiero y yo sano» (Dt 32:39), estableciendo רָפָא como la palabra definitiva para la restauración divina. El Nifal pasivo cubre el ser sanado de enfermedad o aflicción (Is 53:5), mientras que el Piel intensivo denota un tratamiento médico completo, como cuando los médicos embalsamaron a Jacob (Gn 50:2) o los profetas diagnostican las heridas de Israel (Jer 6:14). El participio funciona como título profesional, «médico», tendiendo un puente entre la sanidad humana y la divina. El árabe rafa''a significa «remendar o zurcir», preservando el sentido concreto antiguo de la raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7496', 'spa', 'Sombras o espíritus de los muertos, los espectrales habitantes del Seol en la literatura sapiencial y profética', 'Sustantivo plural evocador que designa las «sombras»: los espíritus debilitados e impotentes de los muertos que moran en el Seol. La palabra aparece en algunos de los pasajes más sobrecogedores sobre la muerte y el más allá en la Biblia hebrea. En Proverbios, la casa de la mujer ajena desciende hasta los refaim (Pr 2:18; 9:18), mientras que Job pregunta si las sombras tiemblan bajo las aguas (Job 26:5). Isaías emplea el término tanto para la burlesca bienvenida a un tirano caído en el Seol (Is 14:9) como para la promesa divina de resurrección (Is 26:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7497a', 'spa', 'Ha-Rafá; el ancestro epónimo de los gigantes filisteos, campeones guerreros abatidos por los hombres de David.', 'Aparece siempre con el artículo definido (הָרָפָה, ''el Rafá''), identificando a un legendario progenitor del clan de gigantes refaítas. La frase ''nacido del Rafá'' (2 Sam 21:16, 18, 20, 22) designa a campeones filisteos de estatura extraordinaria que los guerreros de David derrotaron en combate singular. El relato paralelo en 1 Crónicas 20:6, 8 emplea la variante הָרָפָא. La construcción hebrea trata este nombre como un título dinástico más que como un simple nombre personal, funcionando como patronímico del clan de los refaítas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7497b', 'spa', 'Refaítas — una antigua raza de gigantes que habitaba Canaán y Transjordania antes de la conquista israelita.', 'Refaítas — una antigua raza de gigantes que habitaba Canaán y Transjordania antes de la conquista israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7499', 'spa', 'remedios, medicinas, tratamientos curativos', 'Este sustantivo plural designa medicinas o tratamientos curativos, apareciendo exclusivamente en oráculos proféticos que emplean imágenes médicas para crisis nacionales. Jeremías y Ezequiel lo usan metafóricamente: las naciones que buscan ''remedios'' para sus heridas mortales no encontrarán ninguno. El término enfatiza la futilidad de las soluciones humanas cuando ha caído el juicio divino—ninguna cantidad de medicina puede sanar lo que Dios ha determinado destruir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7502', 'spa', 'extender, sostener, refrescar—desplegar algo plano o proporcionar soporte físico', 'Este verbo captura el acto de extender algo plano, como las escamas de un cocodrilo que dejan marcas en el lodo (Job 41:30), o proporcionar apoyo desde abajo. En Cantares 2:5, el amante pide ser refrescado o sustentado con manzanas, usando imágenes de ser sostenido o apoyado. El término puede describir tanto una extensión literal como un sustento metafórico, compartiendo una conexión semántica con extender un apoyo o cojín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7503', 'spa', 'Hundirse, aflojar, soltar; debilitarse; ser perezoso; abandonar; cesar, estar quieto; dejar caer; debilitar.', 'Hundirse, aflojar, soltar; debilitarse; ser perezoso; abandonar; cesar, estar quieto; dejar caer; debilitar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7504', 'spa', 'debil, flojo, sin fuerzas', 'Este adjetivo describe debilidad fisica o moral, flojedad o falta de vigor, ya sea en personas, manos (simbolo de fortaleza) o determinacion. El termino aparece frecuentemente en contextos militares o de coraje, donde las ''manos flojas'' representan desanimo o incapacidad para combatir. Abarca tanto la debilidad corporal como el desfallecimiento psicologico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7508', 'spa', 'Refidim — campamento israelita en el desierto, cerca del Sinaí; lugar del agua de la roca y la batalla contra Amalec', 'Refidim fue una estación crucial durante el Éxodo, ubicada en la península del Sinaí cerca del monte Horeb. Allí ocurrieron dos eventos decisivos: la provisión milagrosa de agua de la roca cuando el pueblo tenía sed (Éx 17:1) y la batalla contra Amalec, en la que Moisés sostuvo sus manos en alto para obtener la victoria (Éx 17:8). Los israelitas partieron de Refidim para llegar al desierto del Sinaí (Éx 19:2), y Números 33:14-15 lo registra en el itinerario de las etapas del viaje. La Septuaginta lo transcribe como Ῥαφιδείν.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7509', 'spa', 'Refaías — nombre propio (''Yah ha sanado'') usado para cinco individuos distintos en Crónicas y Nehemías', 'Refaías es un nombre propio que significa ''Yah ha sanado'', portado por al menos cinco individuos distintos en la Biblia hebrea. Entre ellos se cuentan un descendiente de David (1 Cr 3:21), un jefe militar simeonita que venció a los amalecitas en el monte Seir (1 Cr 4:42), un jefe de clan de Isacar (1 Cr 7:2), un descendiente de Saúl por vía de Jonatán (1 Cr 9:43, variante de Rafa en 8:37) y un funcionario postexílico que ayudó a reconstruir el muro de Jerusalén bajo Nehemías (Neh 3:9). La Septuaginta lo transcribe de diversas formas como Ῥαφαΐα y Ῥαφαλά, conservando el elemento teofórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7515', 'spa', 'pisotear, enturbiar pisando—enlodar o contaminar agua al pisar con los pies', 'Este verbo describe la acción de enturbiar agua pisoteándola, particularmente vívido en las imágenes de Ezequiel donde Faraón es comparado con un cocodrilo que agita los ríos. El participio Nifal en Proverbios 25:26 describe una fuente que ha sido enlodada, ilustrando el compromiso moral. La palabra lleva un sentido de pisoteo destructivo que arruina lo que antes estaba limpio, ya sea agua literal o pureza metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7521', 'spa', 'Verbo que expresa el arco completo del favor divino y humano — desde el deleite interior hasta la aceptación exterior. En su forma Qal activa, רָצָה d', 'Verbo que expresa el arco completo del favor divino y humano — desde el deleite interior hasta la aceptación exterior. En su forma Qal activa, רָצָה describe a Dios complaciéndose en los caminos de una persona (1 Cr 29:17) o en la ofrenda de un adorador (Mal 1:8). El Nifal pasivo transmite el estado de ser hallado aceptable, un concepto crucial en la ley levítica del sacrificio: ¿será esta ofrenda «aceptada» a favor del oferente (Lv 1:4)? Un uso especializado notable aparece en la teología del año sabático de Lv 26:34-43, donde la tierra desolada finalmente «disfruta» sus sábados perdidos durante el exilio. El participio pasivo produce el adjetivo «favorecido», aplicado a la bendición tribal de Aser (Dt 33:24) y a la posición de Mardoqueo entre su pueblo (Est 10:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7522', 'spa', 'רָצוֹן es la palabra para lo que Dios quiere y lo que alegra a Dios. Aparece 56 veces en la Biblia hebrea, y en casi todos los casos describe una disp', 'רָצוֹן es la palabra para lo que Dios quiere y lo que alegra a Dios. Aparece 56 veces en la Biblia hebrea, y en casi todos los casos describe una disposición que fluye hacia abajo — de Dios hacia las personas, de un rey hacia sus súbditos. Dt 33:16 invoca «el favor (רָצוֹן) del que habitó en la zarza», y Sal 5:12 promete que YHWH rodeará al justo «de favor como con un escudo». Pero רָצוֹן no es solo benevolencia divina: también designa la voluntad humana, como cuando los hermanos en Gn 49:6 actúan según su propio רָצוֹן, o cuando Esdras insta a Israel a cumplir el רָצוֹן de Dios (Esd 10:11). Un sentido cúltico especializado surge en Levítico, donde los sacrificios se ofrecen לְרָצוֹן — «para aceptación» — ante el SEÑOR, fórmula técnica repetida a lo largo de la legislación sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7523', 'spa', 'Asesinar, matar ilicitamente; el homicida; usado en la prohibicion del Decalogo contra la muerte ilicita.', 'Asesinar, matar ilicitamente; el homicida; usado en la prohibicion del Decalogo contra la muerte ilicita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7526', 'spa', 'Rezín, rey de Aram-Damasco que se alió con Pécaj contra Judá en la crisis siro-efraimita', 'Nombre del último rey independiente de Aram-Damasco, cuya fatídica alianza con Pécaj de Israel contra Judá desencadenó uno de los momentos proféticos más trascendentales del Antiguo Testamento. Cuando Rezín y Pécaj marcharon sobre Jerusalén para reemplazar a Acaz con un rey títere, la aterrorizada corte judía recibió la profecía del Emmanuel: ''el Señor mismo os dará señal'' (Is 7:1-14). Acaz, en cambio, acudió a Asiria; Tiglat-pileser III respondió conquistando Damasco y dando muerte a Rezín (2 R 16:9), poniendo fin a siglos de independencia aramea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7531a', 'spa', 'ritsepah — pavimento, suelo empedrado; superficie pavimentada en atrios del templo o salones de palacio', 'Sustantivo femenino que designa una superficie pavimentada con piedras — un suelo de losas ensambladas en un edificio monumental o patio ceremonial. Aparece en tres contextos arquitectónicos: el templo visionario de Ezequiel, donde el pavimento recubre el atrio exterior y bordea las puertas (Ez 40:17-18; 42:3); el templo de Salomón, donde el pueblo se postra sobre el pavimento durante la dedicación (2 Cr 7:3); y el palacio persa en Susa, donde el suelo se describe con materiales exóticos (Est 1:6). En cada caso, el pavimento señala un espacio ceremonial significativo — el lugar donde cielo y tierra se encuentran en adoración o donde se exhibe el esplendor real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7532', 'spa', 'Rizpa (nombre propio femenino, posiblemente ''brasa ardiente, piedra caliente'')', 'Este nombre femenino identifica a la concubina de Saúl, madre de dos hijos ejecutados por los gabaonitas. Su vigilia protegiendo los cuerpos de sus hijos de los animales carroñeros (2 Samuel 21:10) constituye una de las imágenes maternas más conmovedoras de toda la Escritura. El nombre posiblemente deriva de ''brasa ardiente'' o ''piedra caliente'', aunque la etimología es incierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7533', 'spa', 'Aplastar, magullar, quebrantar; oprimir; luchar mutuamente; los aplastados u oprimidos como categoría social.', 'Aplastar, magullar, quebrantar; oprimir; luchar mutuamente; los aplastados u oprimidos como categoría social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7534', 'spa', 'flaco, delgado—describiendo ganado demacrado en el sueño de Faraón', 'Este adjetivo aparece exclusivamente en el relato del sueño de Faraón en Génesis 41, describiendo las vacas demacradas que devoraron a las sanas. La palabra pinta un cuadro de extrema delgadez o flacura, enfatizando la severidad del hambre venidera. La repetición a través de tres versículos (41:19, 20, 27) subraya la naturaleza perturbadora de la visión que preocupó a Faraón y requirió la interpretación de José.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7535', 'spa', 'Solo, solamente, ciertamente — partícula restrictiva o aseverativa que limita o enfatiza una afirmación; raramente ''excepto''.', 'Una partícula hebrea pequeña pero poderosa: רַק acota el enfoque con precisión quirúrgica. En la mayoría de sus 109 apariciones restringe una afirmación —«solo a vosotros he conocido de todas las familias de la tierra» (Am 3:2)— o la intensifica con fuerza aseverativa: ''ciertamente, sin duda.'' Da forma a algunas de las declaraciones más memorables de la Biblia, desde la sombría observación divina de que los pensamientos humanos eran «solo mal continuamente» (Gn 6:5) hasta la preocupada confesión de Abraham: «ciertamente no hay temor de Dios en este lugar» (Gn 20:11). Las traducciones convergen estrechamente: español solo/solamente, francés seulement, alemán nur — todas reflejan el núcleo restrictivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7536', 'spa', 'saliva, escupitajo—saliva, especialmente en contextos de desprecio o tiempo breve', 'Este sustantivo se refiere a saliva o escupitajo, apareciendo en contextos de escupir con desprecio (Isaías 50:6, Job 30:10) y como medida del momento más breve. Job 7:19 usa la vívida frase ''mientras trago mi saliva'' para describir un instante de tiempo, mostrando cómo los procesos corporales podían convertirse en modismos para brevedad temporal. El término captura tanto la sustancia física como sus asociaciones culturales con el desdén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7538', 'spa', 'Podredumbre, carcoma — figurado para la corrupción interna que carcome los huesos o una nación', 'El hebreo רָקָב designa podredumbre o descomposición, siempre usado figuradamente en la Escritura. En Oseas 5:12 Dios mismo es «como podredumbre» para la casa de Judá, emparejado con la imagen de la polilla, retratando el juicio divino como una desintegración interna y lenta. Proverbios 12:4 y 14:30 hablan de «podredumbre de huesos», donde la envidia o una esposa deshonrosa corroe a la persona desde adentro. En Habacuc 3:16 el propio cuerpo del profeta se descompone de pavor. Los términos españoles ''podredumbre'' y ''carcoma'' captan bien este sentido de deterioro progresivo e irreversible, en contraste con la destrucción repentina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7540', 'spa', 'Saltar, brincar, danzar — expresando gozo, poder divino o movimiento vigoroso en contextos literales y festivos.', 'Verbo vívido de movimiento exuberante presente en salmos, profecía y literatura sapiencial. En el Salmo 114:4, los montes mismos ''saltaron como carneros'' ante la presencia de Dios, imagen sobrecogedora de la creación brincando ante el poder divino. David danza ante el arca con tal abandono que Mical lo menosprecia (1 Cr 15:29). La misma palabra describe a niños saltando en juego despreocupado (Job 21:11) y langostas que brincan sobre las cumbres como carros de guerra (Jl 2:5). El español ''saltaron/danzan'' y el francés ''bondir'' abarcan toda la gama desde la danza gozosa hasta el salto poderoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7541', 'spa', 'Sien (de la cabeza) — el lado de la frente por encima del pómulo', 'רַקָּה se refiere específicamente a la sien, la zona delgada y vulnerable entre la frente y la oreja. Aparece en dos contextos vívidos: Jael clava una estaca de tienda en la sien de Sísara (Jue 4:21-22; 5:26), y la sien de la amada se compara con una rodaja de granada detrás de su velo (Cnt 4:3; 6:7). El español ''sien'' y el francés ''tempe'' reflejan con precisión este término anatómico, mientras que el alemán ''Schläfe'' comparte el mismo vínculo etimológico con el hueso delgado del cráneo. Los dos contextos ilustran los polos del término: vulnerabilidad mortal y delicada belleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7543', 'spa', 'Mezclar o preparar ungüentos y especias; como participio, perfumista o preparador de ungüentos profesional', 'Verbo que significa mezclar o preparar aceites aromáticos y ungüentos, central en la elaboración del aceite sagrado de unción en Éxodo. En su forma participial funciona como título profesional: el «perfumista» o «preparador de ungüentos» que compone el incienso y el aceite santo. Eclesiastés 10:1 extiende la imagen de manera memorable: las moscas muertas hacen heder el ungüento del perfumista — un proverbio sapiencial que convierte el arte del perfumista en metáfora de cómo pequeñas corrupciones arruinan un gran esfuerzo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7549', 'spa', 'Expansión, firmamento, bóveda celeste; la superficie extendida que separa las aguas de arriba de las aguas de abajo.', 'Expansión, firmamento, bóveda celeste; la superficie extendida que separa las aguas de arriba de las aguas de abajo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7550', 'spa', 'Oblea u hojuela fina sin levadura, usada en los rituales sacrificiales y de consagración israelitas', 'Sustantivo masculino que designa una oblea fina y plana de pan sin levadura, que aparece siempre en contextos rituales. Estas delicadas tortas acompañaban la consagración de los sacerdotes (Éx 29:2, 23; Lv 8:26), las ofrendas de cereal (Lv 2:4; 7:12), la conclusión del voto nazareo (Nm 6:15, 19) y el servicio diario del templo (1 Cr 23:29). La Septuaginta griega lo traduce como laganon, una torta fina. Su emparejamiento constante con matstsot (pan sin levadura) en todas las ocurrencias confirma que se trataba de un tipo específico de producto horneado ritualmente puro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7551', 'spa', 'Abigarrar, bordar; como sustantivo, bordador; en Pual, ser hábilmente tejido o labrado.', 'Término de artesanía textil arraigado en el arte de trabajar diseños con hilos de colores. Como participio Qal designa al ''bordador'', el artesano hábil que creaba las cortinas, mamparas y vestiduras multicolores del Tabernáculo (Éx 26:36; 27:16; 28:39; 35:35; 36:37; 38:18, 23; 39:29). El pasivo Pual en el Salmo 139:15 es sobrecogedor: el salmista declara ''fui entretejido'' en las profundidades ocultas, comparando la formación divina del ser humano en el vientre con la labor intrincada de un bordador. Los cognados del árabe ''raqama'' y del etiópico confirman el significado central de marcar o estampar con color.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7552', 'spa', 'Requem; nombre propio de un rey madianita, descendientes calebitas y una ciudad benjaminita.', 'El nombre Requem (רֶקֶם) aparece en varios contextos bíblicos distintos. Identifica a uno de los cinco reyes madianitas muertos junto con Balaam (Núm 31:8; Jos 13:21), a un descendiente de Caleb a través de Hebrón en la genealogía de Judá (1 Cr 2:43-44), un nombre manasita en Galaad (1 Cr 7:16) y una ciudad en el territorio de Benjamín (Jos 18:27). La Septuaginta lo traduce de diversas formas como Ροκομ y Ρεκεμ, reflejando variación dialectal. Este nombre propio cubre tanto personas como un lugar geográfico dentro del registro bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7553', 'spa', 'Tela abigarrada, bordado; tejido o tela bordada, a menudo prendas o textiles ricamente decorados', 'El sustantivo רִקְמָה designa una tela abigarrada o multicolor, ya sea producida por tejido o por bordado. En la suntuosa alegoría de Ezequiel sobre Jerusalén, Dios la viste con רִקְמָה (Ez 16:10, 13, 18): prendas ricamente estampadas que simbolizan el favor divino. El mismo vocablo describe las mercancías de lujo del comercio de Tiro (Ez 27:7, 16, 24) y el plumaje multicolor del águila en Ezequiel 17:3. En el cántico de victoria de Débora, el botín incluye רִקְמָתַיִם, un par de paños bordados, premio tangible y concreto de la guerra (Jue 5:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7554', 'spa', 'Batir, apisonar, extender; martillar metal en láminas; recubrir con metal batido', 'Verbo arraigado en la acción física de golpear o aplanar, que abarca desde la creación cósmica hasta el trabajo del metal. Dios ''extiende'' la tierra y martilla el firmamento (Job 37:18; Is 42:5; 44:24), la misma raíz detrás de רָקִיעַ, la ''expansión'' de Génesis 1. En ira, Ezequiel patea con el pie (Ez 6:11), y David aplasta a sus enemigos bajo sus pies (2 S 22:43). En el ámbito artesanal, el verbo describe al orfebre que bate el oro en láminas delgadas (Éx 39:3; Nm 16:39). La palabra tiende un puente entre el taller y el cosmos con una sola imagen vívida de fuerza aplicada para aplanar y extender.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7560', 'spa', 'Firmar, escribir (un decreto); ser inscrito, registrado por escrito — verbo arameo en Daniel', 'El verbo arameo רְשַׁם abarca el acto de escribir y firmar documentos oficiales, y aparece exclusivamente en Daniel en medio de las intrigas políticas de la corte medopersa. Su sentido activo predomina: Darío firma el decreto irrevocable contra la oración (Dn 6:8-10, 12-13), y el verbo capta tanto la redacción del documento como la firma que lo autentica. El sentido pasivo emerge cuando la escritura misteriosa es inscrita en la pared del palacio de Belsasar (Dn 5:24-25) — palabras escritas por ninguna mano humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7561', 'spa', 'Ser malvado, obrar con maldad; en Hifil, condenar como culpable o hacer el mal activamente; abarca corrupcion moral y veredicto juridico.', 'Ser malvado, obrar con maldad; en Hifil, condenar como culpable o hacer el mal activamente; abarca corrupcion moral y veredicto juridico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7562', 'spa', 'Maldad, culpa — el mal moral como cualidad del carácter o la conducta, opuesto al orden justo de Dios', 'Maldad, culpa — el mal moral como cualidad del carácter o la conducta, opuesto al orden justo de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7563', 'spa', 'Impío, malvado — persona moralmente corrupta opuesta a los caminos de Dios; también culpable en contextos forenses.', 'Una de las palabras clave del vocabulario moral de la Biblia hebrea, רָשָׁע se erige como el gran antónimo de צַדִּיק (''justo''). A lo largo de 263 apariciones, designa abrumadoramente al moralmente impío — aquellos cuya conducta desafía el orden divino, desde Faraón hasta los enemigos intrigantes de los Salmos. La palabra porta peso teológico: los impíos no son meramente infractores de la ley, sino quienes resisten el orden moral divino en sí mismo. En un pequeño grupo de pasajes forenses (Nm 35:31, Dt 25:1-2), el sentido se estrecha hacia la culpabilidad legal — alguien merecedor de condena. El alemán Gottlose (''sin Dios'') revela la interpretación teológica, mientras que el español impío y el francés méchant captan cada uno una faceta distinta de su fuerza moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7564', 'spa', 'Maldad, impiedad; culpa o conducta reprensible atribuida a una persona o nación. Sustantivo femenino que denota perversidad moral o conducta malvada, ', 'Maldad, impiedad; culpa o conducta reprensible atribuida a una persona o nación. Sustantivo femenino que denota perversidad moral o conducta malvada, empleado en la literatura legal, profética y sapiencial. En Deuteronomio caracteriza la depravación colectiva de las naciones cananeas que justificó su desposesión (Dt 9:4-5), mientras que en Proverbios personifica la naturaleza autodestructiva del impío (Pr 11:5; 13:6). Zacarías la personifica dramáticamente como una mujer sellada en un efa (Zac 5:8). El término porta dimensiones tanto abstractas como personales, desde la maldad nacional hasta la culpabilidad individual merecedora de castigo (Dt 25:2). El alemán ''Gottlosigkeit'' (impiedad) y el español ''maldad/impiedad'' captan conjuntamente su doble registro ético-religioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7565', 'spa', 'Llama, dardo de fuego o pestilencia; desde las brasas del amor hasta flechas divinas de plaga y rayos', 'Palabra hebrea evocadora enraizada en la imaginería del fuego. En Cantares 8:6 describe las llamas del amor — «sus reshef-destellos son destellos de fuego» — donde «brasas» y «chispas» transmiten admirablemente el calor consumidor de la pasión. En Deuteronomio 32:24 y Habacuc 3:5 se convierte en un agente divino aterrador — pestilencia y plaga marchando ante Dios, evocando la deidad cananea Resheph. Los Salmos lo emplean para rayos y flechas de fuego que caen en juicio (Sal 76:3; 78:48). Job 5:7 nos ofrece los memorables «hijos de resheph» — chispas que vuelan hacia arriba, metáfora de la inevitabilidad del sufrimiento humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7568', 'spa', 'Red para atrapar presas (literal o figurada); también enrejado o rejilla, especialmente del altar del tabernáculo', 'Red para atrapar presas (literal o figurada); también enrejado o rejilla, especialmente del altar del tabernáculo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7569', 'spa', 'cadena—eslabones metálicos ornamentales o de restricción, especialmente de oro', 'Este sustantivo denota cadenas, particularmente las ornamentales hechas de oro utilizadas en el templo de Salomón (1 Reyes 6:21) y aquellas para atar cautivos (Ezequiel 7:23). La palabra aparece en contextos donde las cadenas sirven funciones decorativas o de restricción. El uso en el templo sugiere artesanía fina, mientras que la referencia de Ezequiel señala las cadenas de cautiverio que aguardan a Jerusalén, creando un marcado contraste entre belleza y esclavitud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7570', 'spa', 'hervir, bullir—causar burbujeo mediante calor, literal o figuradamente', 'Este verbo describe la acción de hervir o hacer que algo bulla con calor. Ezequiel 24:5 lo utiliza en el mandato de hervir la olla de cocción, parte de una metáfora extendida sobre el juicio de Jerusalén. Job lo usa dos veces: una vez para entrañas hirviendo de turbulencia emocional (30:27), y otra para Leviatán haciendo hervir el abismo como una olla (41:31). El término conecta el hervir literal de la cocina con la agitación metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7574', 'spa', 'Retama, arbusto de retama (planta del desierto)', 'Este sustantivo designa un arbusto desértico, probablemente la retama blanca (Retama raetam), común en las regiones áridas del Cercano Oriente. Célebre como el refugio de Elías en el desierto, también aparece en descripciones de penuria extrema y como combustible para brasas. Las raíces profundas de la planta, su escasa sombra y su madera que arde intensamente forman parte destacada de la imaginería bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7579', 'spa', 'Sacar agua de un pozo o manantial; por extensión, la persona que saca agua.', 'Sacar agua de un pozo o manantial; por extensión, la persona que saca agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7580', 'spa', 'Rugir como un león, usado de bestias, enemigos y Dios en poder o juicio; raramente, gemir de angustia.', 'Rugir como un león, usado de bestias, enemigos y Dios en poder o juicio; raramente, gemir de angustia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7581', 'spa', 'Rugido (de un león, literal o figurado); gemido o clamor angustioso (de una persona en aflicción)', 'El sustantivo שְׁאָגָה abarca dos sonidos contrastantes: el rugido feroz de un león y el gemido angustioso del ser humano que sufre. Como rugido leonino, evoca un poder aterrador: Isaías 5:29 compara a los ejércitos invasores con un león rugiente, y Ezequiel 19:7 describe a un rey conquistador cuyo rugido devasta la tierra. Como gemido humano, da voz a las profundidades de la angustia personal: las «palabras de mi gemido» de David en el Salmo 22:1 —el salmo que Jesús citó desde la cruz— y los suspiros de Job que vienen en lugar del pan (Job 3:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7582', 'spa', 'Derrumbarse en ruinas, ser devastado; rugir o causar estruendo; hacer desolado (Hifil causativo).', 'Verbo de ruido violento y destrucción que evoca el estruendoso derrumbe de ciudades y el rugir de naciones hostiles. En Isaías 6:11, la devastadora comisión del profeta continúa ''hasta que las ciudades se derrumben en ruinas'' y la tierra quede desolada — todo el peso de la finalidad del juicio. Isaías 17:12-13 aplica el término al aterrador rugir de naciones que avanzan como muchas aguas, aunque Dios las reprende y huyen. El Hifil causativo en 2 Reyes 19:25 e Isaías 37:26 revela que Dios mismo ordenó las campañas del rey asirio ''para convertir ciudades fortificadas en montones desolados''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7585', 'spa', 'Se refiere casi exclusivamente a la morada subterránea de los muertos, el destino sombrío de todos los que mueren. Los hablantes de hebreo no concebía', 'Se refiere casi exclusivamente a la morada subterránea de los muertos, el destino sombrío de todos los que mueren. Los hablantes de hebreo no concebían el Seol como un lugar de castigo únicamente; tanto justos como impíos descienden allí. Jacob se lamenta de que bajará al Seol llorando por José (Gn 37:35), y el salmista agradece a Dios por rescatar su alma de sus profundidades más bajas (Sal 86:13). La etimología podría conectarse con שָׁאַל (''preguntar, inquirir''), posiblemente en referencia a la nigromancia. En un pasaje disputado (Is 7:11), la forma podría ser en realidad el imperativo del verbo «pedir» en lugar del sustantivo Seol, cuando se le dice a Acaz que pida una señal del Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7586', 'spa', 'Saúl; nombre propio que significa ''pedido [a Dios],'' llevado por el primer rey de Israel y varias otras figuras.', 'שָׁאוּל (''pedido'') es conocido sobre todo como el nombre del primer rey de Israel, el alto benjamita hijo de Cis cuyo turbulento reinado domina 1 Samuel. El nombre deriva de la raíz שָׁאַל (''pedir''), reflejando la petición del pueblo de un monarca (1 S 8:5). Más allá del rey Saúl, el mismo nombre identifica a un rey edomita de Rejobot junto al río (Gn 36:37), un hijo de Simeón con una mujer cananea (Gn 46:10) y un antepasado levita (1 Cr 6:9). Las traducciones entre lenguas uniformemente transliteran en lugar de traducir: español Saúl, francés Saül, alemán Saul.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7588', 'spa', 'Rugido, tumulto, estruendo — el fragor ensordecedor de aguas, ejércitos o multitudes; una vez la desolación rugiente de un pozo destructor.', 'Rugido, tumulto, estruendo — el fragor ensordecedor de aguas, ejércitos o multitudes; una vez la desolación rugiente de un pozo destructor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7589', 'spa', 'desprecio, desdén—menosprecio profundo guardado en el alma o corazón', 'Este sustantivo aparece solamente en Ezequiel, describiendo el desprecio o desdén malicioso que los enemigos albergan contra Israel. La frase ''con desprecio en el alma'' (25:15) o ''con todo desprecio de alma'' (25:6) enfatiza que esto no es desdén casual sino odio profundamente arraigado. Ezequiel usa este término para caracterizar las actitudes hostiles de las naciones circundantes, proporcionando fundamentos para el juicio de Dios contra ellas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7590', 'spa', 'despreciadores, los que tratan con desprecio—personas que menosprecian o muestran desdén', 'Esta forma participial, apareciendo solamente en Ezequiel, describe a aquellos que activamente tratan a otros con desprecio o desdén. La palabra caracteriza a pueblos circundantes—hijas de los filisteos (16:57) y varios vecinos (28:24, 26)—que miraban con desprecio a Israel. El término captura desprecio continuo y habitual en lugar de un solo acto de menosprecio, retratando una actitud establecida de desdén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7592', 'spa', 'Preguntar, inquirir, pedir, solicitar, tomar prestado o prestar; abarca la indagación, la petición y la transacción de préstamo.', 'שָׁאַל es el verbo por excelencia de la necesidad humana expresada en voz alta — ya sea buscando información, solicitando un favor o negociando un préstamo. Su campo semántico va desde la pregunta sencilla («¿Cuál es tu nombre?» Gn 32:29) hasta la petición desesperada (la súplica de Ana por un hijo, 1 S 1:20), e incluso se extiende a la economía del préstamo. El árabe sa''ala conserva el mismo núcleo de indagación verbalizada, mientras que la distinción coreana entre mul-eotda (preguntar) y guhaetda (solicitar) expone la línea entre buscar información y buscar un favor que el hebreo deja implícita. El juego de palabras con el nombre de Samuel — «se lo pedí a Jehová» — muestra cuán profundamente está tejido este verbo en la teología narrativa de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7593', 'spa', 'Preguntar, inquirir; solicitar o exigir (arameo)', 'El verbo arameo שְׁאֵל refleja su cognado hebreo שָׁאַל y aparece exclusivamente en las secciones arameas de Esdras y Daniel. Abarca dos actos de habla relacionados: formular una pregunta para obtener información y hacer una solicitud o exigencia formal. Cuando el gobernador Tatnai interrogó a los constructores judíos, les ''preguntó'' sus nombres y autoridad (Esd 5:9-10), en un acto de indagación judicial. Pero cuando Artajerjes decreta que todo lo que Esdras ''os pida'' debe concederse (Esd 7:21), el verbo pasa de la indagación a la petición con autoridad. El español distingue ambos sentidos con nitidez: ''preguntamos'' frente a ''os pida''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7596', 'spa', 'Petición, solicitud; un ruego formal dirigido a una figura de autoridad, o aquello que se concede en respuesta. Denota una solicitud o petición hecha ', 'Petición, solicitud; un ruego formal dirigido a una figura de autoridad, o aquello que se concede en respuesta. Denota una solicitud o petición hecha a alguien con autoridad, ya sea un rey (las repetidas peticiones de Ester a Asuero) o Dios mismo (la oración de Ana en 1 Sam 1:27). El término transita naturalmente del acto de pedir hacia ''lo pedido'', como cuando Ana nombra a Samuel ''porque se lo pedí al SEÑOR'' y Elí confirma ''el SEÑOR te conceda tu petición''. En un caso especializado (1 Sam 2:20), se acerca al sentido de ''préstamo'', algo confiado que Dios retribuirá. El español ''petición'' y el francés ''demande'' captan el registro formal y cortesano del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7597a', 'spa', 'Salatiel; ''Le pedí a Dios'', padre de Zorobabel, líder del retorno postexílico a Jerusalén.', 'El nombre Salatiel (שְׁאַלְתִּיאֵל) significa ''le he pedido a Dios'', expresando una dependencia orante de la provisión divina. Se lo identifica como el primer hijo del rey Joaquín (1 Cr 3:17) y como padre de Zorobabel, el gobernador que dirigió la reconstrucción del templo tras el exilio babilónico (Hag 1:1; Esd 3:2, 8; Neh 12:1). La Septuaginta lo traduce como Σαλαθιηλ, forma que pasó a las genealogías del Nuevo Testamento. El español conserva varias formas: ''Salatiel'' y ''Sealtiel''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7597b', 'spa', 'Sealtiel—padre de Zorobabel en el período postexílico', 'Este nombre personal identifica al padre de Zorobabel, el gobernador que dirigió el primer regreso del exilio babilónico. Hageo menciona a Sealtiel tres veces (1:12, 14; 2:2) en la fórmula ''Zorobabel hijo de Sealtiel'', estableciendo la autoridad genealógica del liderazgo postexílico. El nombre aparece como una forma alternativa de Sealtiel encontrada en otros textos bíblicos, significando ''He pedido a Dios''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7599', 'spa', 'Estar tranquilo, reposar seguro; habitar sin ser perturbado, libre de amenaza o calamidad', 'Este verbo en forma Piel expresa el estado de estar tranquilo, seguro y sin perturbación alguna. En Jeremías 30:10 y 46:27, Dios promete que Israel volverá y estará ''tranquilo sin que nadie lo atemorice,'' emparejando שַׁאֲנַן con שָׁקַט (estar quieto). En Jeremías 48:11 la misma raíz describe irónicamente la falsa complacencia de Moab. Proverbios 1:33 asegura que quien escucha a la sabiduría ''habitará seguro y estará tranquilo, sin temor del mal.'' El español ''tranquilo'' capta con precisión esa calma asentada y sin sobresaltos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7600', 'spa', 'Tranquilo, seguro; abarcando desde la genuina serenidad hasta la autocomplacencia y la arrogancia insolente.', 'Adjetivo cuyo significado gira drásticamente según el contexto, recorriendo todo el espectro desde la paz bendita hasta la complacencia condenada. Isaías lo usa positivamente para Jerusalén como ''morada tranquila'' (33:20) y para los ''lugares de reposo apacibles'' de Israel (32:18), pero apenas unos versículos antes reprende a las ''mujeres que están tranquilas'' (32:9, 11). Amós abre su oráculo de ayes contra los ''que están tranquilos en Sion'' (6:1), y el salmista lamenta el desprecio de los complacientes (123:4). El francés ''insouciant'' (despreocupado, negligente) captura con brillantez ese terreno medio peyorativo. En su forma más extrema, denota la ''arrogancia'' de Senaquerib ante Dios (2 R 19:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7602a', 'spa', 'Jadear, resollar; figuradamente anhelar con intensidad o apresurarse', 'Un verbo arraigado en la experiencia visceral de la respiración agitada. Isaías 42:14 lo empareja con נָשַׁם cuando Dios declara «resollaré y jadearé a la vez», mientras los asnos monteses de Jeremías se paran en las alturas desnudas y «jadean por aire» (Jer 14:6). El acto físico de jadear se convierte en metáfora de deseo intenso en Job 7:2, donde el siervo «anhela» la sombra, y en el Salmo 119:131, donde el salmista abre su boca y jadea por los mandamientos de Dios. Eclesiastés 1:5 lleva la imagen más lejos: el sol «se apresura» de vuelta a su lugar de salida, jadeando como un corredor que completa su circuito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7602b', 'spa', 'Pisotear, aplastar, perseguir agresivamente; tragar, devorar', 'Esta segunda raíz שָׁאַף (II) es distinta de la más común שׁאף que significa ''jadear'' o ''resollar''. BDB la conecta con שׁוּף (''aplastar, magullar''), y sus apariciones se concentran en salmos de lamento y juicio profético. En los Salmos describe a enemigos hostiles que ''pisotean'' al salmista (Sal 56:1-2; 57:3), mientras que Amós la emplea como una acusación devastadora: los poderosos de Israel ''pisotean a los pobres'' (Am 2:7; 8:4). La única aparición en Ezequiel (36:3) cambia a una imagen de consumo: la tierra fue ''tragada'' por las naciones circundantes. El español capta la violencia con precisión: ''los que pisotean'' y ''tragaron''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7603', 'spa', 'Levadura; masa fermentada usada para leudar pan, prohibida ritualmente en Pascua y ofrendas de cereal', 'שְׂאֹר designa el agente leudante, la masa fermentada que se reserva para hacer crecer la siguiente hornada de pan. Sus cinco apariciones pertenecen exclusivamente al ámbito ritual: debe eliminarse de los hogares israelitas durante la Fiesta de los Panes sin Levadura (Éx 12:15, 19; 13:7; Dt 16:4) y está prohibida en las ofrendas de cereal sobre el altar (Lv 2:11). La concordancia interlingüística es notable: español ''levadura,'' francés ''levain'' y alemán ''Sauerteig'' señalan unánimemente un mismo referente concreto, confirmando un sentido único y estable en todas las atestaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7604', 'spa', 'Quedar, sobrar, sobrevivir; como participio, el remanente o supervivientes; en Hifil, dejar restante o perdonar la vida.', 'שָׁאַר es el vocabulario primario de la Biblia hebrea para la supervivencia y el remanente — lo que perdura después de que la destrucción, la partida o el juicio divino han arrasado. En su forma Nifal, describe a los familiares que quedan tras la hambruna (Gn 47:18), a los supervivientes de una derrota militar, o al remanente fiel que persiste después del juicio de Dios. La forma participial se convirtió en un término teológico cuasi técnico: ''el remanente'' (הַנִּשְׁאָרִים) — aquellos a quienes Dios preservó. El Hifil causativo invierte la perspectiva, del superviviente a quien determina la supervivencia: Dios o un conquistador deliberadamente ''deja restante'' o ''perdona.'' El español quedar/dejar refleja fielmente este eje Nifal-Hifil de supervivencia pasiva frente a preservación activa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7605', 'spa', 'Remanente, resto, residuo — lo que queda de un pueblo, cantidad o registro narrativo después de una merma o juicio', 'Remanente, resto, residuo — lo que queda de un pueblo, cantidad o registro narrativo después de una merma o juicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7606', 'spa', 'Resto, remanente — sustantivo arameo para lo que queda; pueblos, compañeros o reinos en Esdras y Daniel', 'El sustantivo arameo שְׁאָר (she''ar) significa ''resto, remanente, lo demás'', y funciona como cognado arameo del hebreo שְׁאָר. Aparece exclusivamente en las porciones arameas de Esdras y Daniel. En Esdras, designa con frecuencia a los pueblos restantes asentados en Samaria por los asirios — ''el resto de las naciones que el grande y noble Asnapar deportó'' (Esd 4:9-10) — y se emplea en la correspondencia oficial para dirigirse a ''el resto de sus compañeros'' (Esd 4:17; 7:18). En Daniel, describe lo que queda de un reino destruido: la cuarta bestia devoraba y pisoteaba ''el resto'' (Dn 7:7, 12, 19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7607', 'spa', 'Carne: tejido corporal; un pariente consanguíneo cercano; alimento o sustento debido a una persona dependiente.', 'Carne: tejido corporal; un pariente consanguíneo cercano; alimento o sustento debido a una persona dependiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7611', 'spa', 'Designa lo que sobrevive o permanece después de una pérdida, destrucción o división. En la literatura profética, porta un peso teológico enorme: la שְ', 'Designa lo que sobrevive o permanece después de una pérdida, destrucción o división. En la literatura profética, porta un peso teológico enorme: la שְׁאֵרִית de Israel es el núcleo fiel que soporta el exilio y el juicio para convertirse en semilla de restauración futura. Miqueas promete que «el remanente de Jacob estará entre las naciones» (Mi 5:7), mientras Jeremías advierte que incluso el remanente de Judá que huyó a Egipto perecerá (Jer 44:28). Más allá de su uso dominante para pueblos sobrevivientes, la palabra ocasionalmente describe material sobrante — el resto de un trozo de madera del que se talló un ídolo (Is 44:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7613', 'spa', 'Exaltación, dignidad; una hinchazón elevada en la piel (médico); el acto de levantarse o elevarse. Derivado de la raíz נָשָׂא (levantar, cargar), este', 'Exaltación, dignidad; una hinchazón elevada en la piel (médico); el acto de levantarse o elevarse. Derivado de la raíz נָשָׂא (levantar, cargar), este sustantivo abarca lo físico y lo exaltado. En la legislación sacerdotal de Levítico 13-14, designa una hinchazón elevada en la piel, un término clínico en el vocabulario diagnóstico de las leyes de pureza. En la poesía y la profecía, asciende a dignidad y majestad: la ''preeminencia'' del primogénito (Gn 49:3), el terror de la ''exaltación'' de Dios (Job 13:11; 31:23), y la autoridad autoderivada de los caldeos (Hab 1:7). Dos pasajes conservan la fuerza verbal de la raíz misma: un ''levantamiento'' (Gn 4:7) y un ''alzarse'' que aterroriza a los poderosos (Job 41:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7614', 'spa', 'Saba — nombre propio de varias personas y del próspero reino árabe famoso por su comercio, oro e incienso', 'Saba — nombre propio de varias personas y del próspero reino árabe famoso por su comercio, oro e incienso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7617', 'spa', 'Tomar cautivo, llevar preso; como participio, un captor o una persona cautiva.', 'Tomar cautivo, llevar preso; como participio, un captor o una persona cautiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7619', 'spa', 'Sebuel / Subael; nombre levítico de un jefe del tesoro gersonita y un músico hemanita.', 'Este nombre aparece en dos variantes ortográficas, Sebuel (שְׁבוּאֵל) y Subael (שׁוּבָאֵל), ambas referidas a figuras levíticas en las listas administrativas de David. Uno es descendiente de Gersón, hijo de Moisés, designado jefe sobre los tesoros del templo (1 Cr 23:16; 26:24). El otro es hijo de Hemán el músico, asignado a una división de cantores del templo (1 Cr 25:4, 20). La Septuaginta traduce ambas formas uniformemente como Σουβαηλ, tratando las variantes como un único nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7620', 'spa', 'Período de siete días (semana) o siete años; también la Fiesta de las Semanas (Shavuot/Pentecostés), que celebra la cosecha del trigo', 'Período de siete días (semana) o siete años; también la Fiesta de las Semanas (Shavuot/Pentecostés), que celebra la cosecha del trigo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7621', 'spa', 'Juramento o promesa jurada, que frecuentemente invoca a Dios como testigo; raramente una maldición o autoimprecación', 'Juramento o promesa jurada, que frecuentemente invoca a Dios como testigo; raramente una maldición o autoimprecación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7622', 'spa', 'Cautividad, exilio; o fortuna/condicion, especialmente en la expresion ''restaurar la cautividad/fortuna de''.', 'Cautividad, exilio; o fortuna/condicion, especialmente en la expresion ''restaurar la cautividad/fortuna de''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7623a', 'spa', 'aquietar, calmar, sosegar—tranquilizar las olas, las emociones o la agitación', 'Este verbo Piel significa aquietar, calmar o traer paz a algo turbulento. Los Salmos lo usan para describir cómo Dios calma el rugido de las olas (65:7, 89:9), mientras que Proverbios 29:11 lo aplica al control del temperamento. El término sugiere una intervención activa para traer quietud, ya sea calmando las olas literales de una tormenta o la agitación emocional metafórica. Representa el poder divino sobre el caos y el autocontrol humano sobre la agitación interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7623b', 'spa', 'Alabar, ensalzar, loar (Piel); en Hitpael, gloriarse o jactarse de algo', 'Un aramaísmo tardío (compárese con el arameo/siríaco shbach, «alabar») usado casi exclusivamente en Salmos y Eclesiastés. En su forma Piel, es una palabra de adoración: «¡Alabadle, pueblos todos!» (Sal 117:1), donde aparece junto a הָלַל como sinónimo cercano de aclamación litúrgica. Los usos en Eclesiastés añaden un matiz secular sorprendente: Qohélet «elogia» la alegría (Ecl 8:15) y «alaba» a los muertos (Ecl 4:2). El reflexivo Hitpael desplaza el foco hacia dentro —«gloriarnos en tu santo nombre» (Sal 106:47 = 1 Cr 16:35)—, distinguiendo la exultación interior de la alabanza dirigida hacia afuera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7624', 'spa', 'Alabar, loar (arameo Pael); glorificar con palabras de honor, usado para alabar a Dios o a ídolos', 'Este verbo arameo en la forma Pael significa alabar o loar, y aparece exclusivamente en Daniel. Daniel alaba al Dios del cielo por revelar el sueño de Nabucodonosor (Dn 2:23), y el rey restaurado alaba al Altísimo tras su humillación (Dn 4:34, 37). El mismo verbo se emplea negativamente para la alabanza de ídolos de oro, plata y piedra (Dn 5:4, 23), creando un agudo contraste teológico entre la adoración verdadera y la falsa. El español ''alabar'' y las formas ''alabo/alabé'' reflejan consistentemente un discurso doxológico dirigido a una deidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7626', 'spa', 'Vara, bastón, cetro o tribu; un palo usado para golpear, disciplinar o gobernar, y por metonimia una división tribal de Israel.', 'שֵׁבֶט es una palabra cuyos significados físico y social están unidos por una sola imagen: el bastón que porta un patriarca marca su autoridad sobre su clan. En su sentido más concreto es una vara para golpear (Éx 21:20), disciplinar a un hijo (Pr 22:15) o trillar grano (Is 28:27). Elevada, esa vara se convierte en cetro — «no será quitado el cetro de Judá» (Gn 49:10) — el bastón real que simboliza el derecho a gobernar. Pero el sentido más frecuente en la Biblia hebrea es el tribal: las doce שְׁבָטִים de Israel, cada ''rama'' del árbol genealógico de Jacob. El árabe preserva ambas líneas: عَصَا para el objeto físico, y سِبْط como cognado directo para el sentido tribal, confirmando que la bifurcación semántica es antigua incluso entre lenguas semíticas hermanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7628a', 'spa', 'Cautividad o cautivos; el estado de ser tomado prisionero o las personas asi capturadas, especialmente en contextos de exilio y juicio divino.', 'Cautividad o cautivos; el estado de ser tomado prisionero o las personas asi capturadas, especialmente en contextos de exilio y juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7633', 'spa', 'Cautiverio (estado); cautivos (conjunto de prisioneros tomados en guerra)', 'El sustantivo femenino שִׁבְיָה abarca tanto la condición abstracta del cautiverio como las personas concretas que lo padecen. Cuando Deuteronomio 21:11 describe a un soldado israelita que ve ''una mujer hermosa entre los cautivos'', la palabra señala a personas reales. Cuando 2 Crónicas 6:37-38 habla de los exiliados arrepintiéndose ''en la tierra de su cautividad'', denota el estado o condición de estar retenido. Jeremías 48:46 emplea ambos sentidos en paralelo: los hijos de Moab van al שְׁבִי y sus hijas a la שִׁבְיָה. La distinción en español entre ''cautivos'' (personas) y ''cautiverio'' (estado) refleja fielmente esta dualidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7635', 'spa', 'senda, camino—una ruta transitada o curso de acción', 'Este sustantivo denota una senda o camino, ya sea un sendero literal o un curso metafórico de vida. El Salmo 77:19 habla poéticamente de la senda de Dios a través del mar durante el Éxodo, una ruta invisible pero real. Jeremías 18:15 lamenta el abandono de Israel de las sendas antiguas por caminos descarriados. El término enfatiza tanto la noción física de un camino transitado como la dimensión ética de seguir rutas establecidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7637', 'spa', 'Séptimo — numeral ordinal del número siete, que marca el séptimo día, mes, año o elemento en una secuencia.', 'שְׁבִיעִי es la forma ordinal del número siete, que aparece 98 veces siempre con artículo definido. Su uso teológicamente más significativo designa el séptimo día — el sábado — establecido en la creación misma (Gn 2:2-3) y reforzado en toda la legislación pentateuca (Éx 12:15-16; 16:26-30). El séptimo mes (Tisri) alberga la temporada festiva más solemne: Trompetas, el Día de la Expiación y Tabernáculos (Lv 23:24-27, 34). El séptimo año trae la liberación de esclavos y el descanso de la tierra (Éx 21:2; 23:11). A través de estos patrones recurrentes, el ordinal ''séptimo'' se vuelve inseparable de la teología del descanso, la plenitud y el tiempo sagrado que el número siete porta a lo largo de toda la Escritura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7639', 'spa', 'Enrejado: ornamento de malla en los pilares del Templo; celosía de ventana; red o trampa (figurado)', 'Enrejado: ornamento de malla en los pilares del Templo; celosía de ventana; red o trampa (figurado)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7641a', 'spa', 'corriente de agua, torrente; Shibolet (palabra de prueba dialectal)', 'Este sustantivo designa primariamente una corriente o torrente de agua, pero es célebre por Jueces 12:6 como la contraseña que los galaaditas usaban para identificar a los efraimitas, quienes la pronunciaban «Sibolet». La diferencia dialectal en la pronunciación de la consonante inicial se convirtió en un marcador étnico mortal. El término abarca tanto la realidad física del agua en movimiento como su papel en la identidad lingüística de las tribus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7641b', 'spa', 'Espiga o cabeza de grano; la punta madura y cargada de semillas de plantas cerealeras como el trigo o la cebada. Este שִׁבֹּלֶת (shibbolet II) designa', 'Espiga o cabeza de grano; la punta madura y cargada de semillas de plantas cerealeras como el trigo o la cebada. Este שִׁבֹּלֶת (shibbolet II) designa la espiga madura, la punta cargada de granos de los tallos de cereal. Domina el célebre sueño del faraón en Génesis 41, donde siete espigas gruesas y siete espigas marchitas simbolizan años de abundancia y de hambruna. El término también aparece en la narración del espigueo de Rut (Rt 2:2) y en la imaginería de la cosecha de Isaías (Is 17:5). Zacarías 4:12 extiende la palabra metafóricamente a las ''puntas'' o racimos en los extremos de las ramas de olivo que flanquean el candelabro de oro. El español ''espigas'' y el inglés ''ears of grain'' captan la especificidad agrícola del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7643', 'spa', 'Sibma (también Sebán); ciudad moabita cerca de Hesbón famosa por sus viñedos.', 'Sibma (שִׂבְמָה), también llamada Sebán (שְׂבָם), era una ciudad en la meseta de Moab cerca de Hesbón, célebre por sus exuberantes viñedos. Aparece en las narraciones de reparto tribal cuando Rubén solicita territorio en Transjordania (Nm 32:3, 38; Jos 13:19) y en los oráculos proféticos que lamentan la devastación de Moab (Is 16:8-9; Jer 48:32). La vívida imagen de Isaías de las ramas de la vid de Sibma extendiéndose hasta el Mar Muerto subraya la fama agrícola de la ciudad. La forma septuaginta Σεβαμα y las traducciones españolas ''Sibma'' y ''Sibmá'' preservan este antiguo topónimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7644', 'spa', 'Sebna, alto funcionario real (mayordomo de palacio y luego secretario) bajo el rey Ezequías de Judá.', 'Nombre propio de un prominente funcionario de gobierno durante el reinado del rey Ezequías, atestiguado tanto en Isaías como en 2 Reyes. Sebna aparece primero como el hombre ''que está sobre la casa'', el mayordomo de palacio, en efecto primer ministro, a quien Isaías reprende por haberse labrado un sepulcro ostentoso (Is 22:15). Posteriormente aparece en un papel reducido como secretario real junto a Eliaquim durante el asedio asirio de Jerusalén (2 R 18:18, 37; Is 36:3, 22). La grafía alterna entre שֶׁבְנָא y שֶׁבְנָה en los relatos paralelos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7645', 'spa', 'Sebanías — nombre propio levítico portado por sacerdotes y levitas en el Judá postexílico', 'Sebanías (también escrito Sebaniahu con el sufijo largo del nombre divino) es un nombre propio portado por varios levitas y sacerdotes del período postexílico. Un sacerdote llamado Sebaniahu tocó la trompeta ante el arca cuando David la trajo a Jerusalén (1 Cr 15:24). Posteriormente, múltiples individuos con este nombre aparecen en la narrativa de Nehemías: levitas que dirigieron la confesión y oración públicas (Neh 9:4-5) y firmantes de la renovación del pacto (Neh 10:4, 10, 12). El nombre puede significar «Yahveh ha hecho crecer» o «Yahveh ha restaurado».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7646', 'spa', 'Verbo enraizado en la experiencia primordial del hambre saciada con abundancia. Dt 8:10 captura el ideal: «Comerás y te saciarás y bendecirás al SEÑOR', 'Verbo enraizado en la experiencia primordial del hambre saciada con abundancia. Dt 8:10 captura el ideal: «Comerás y te saciarás y bendecirás al SEÑOR tu Dios». En el Hifil, Dios se convierte en quien sacia — llenando al hambriento de cosas buenas (Sal 91:16; 81:16). Sin embargo, la misma raíz puede agriarse en exceso: Is 1:11 tiene a Dios declarando «Estoy harto de holocaustos» — no satisfecho sino hastiado. El arco desde el alimento hasta el hartazgo refleja un profundo patrón bíblico: la bendición rechazada se convierte en carga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7647', 'spa', 'Abundancia, plenitud; el estado de tener más que suficiente, especialmente de grano y provisiones', 'Sustantivo masculino que denota abundancia o plenitud, usado casi exclusivamente en la narrativa de José en Génesis 41 para describir los siete años de extraordinario excedente agrícola de Egipto. El sueño del faraón con vacas gordas y espigas llenas apuntaba a esta שָׂבָע: una sobreabundancia de alimentos que José sabiamente almacenó contra la hambruna venidera. Fuera de Génesis, la palabra aparece en Proverbios 3:10, que promete que honrar a Dios llena los graneros hasta rebosar, y en Eclesiastés 5:11, que observa que la abundancia de bienes trae consigo abundancia de quienes los consumen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7648', 'spa', 'Saciedad, plenitud; estar satisfecho especialmente de alimento, pero tambien metaforicamente de gozo o bendicion.', 'Sustantivo masculino que expresa el estado de plena satisfaccion, de haber comido o recibido lo suficiente. La mayoria de sus apariciones se refieren al sustento fisico: comer pan hasta saciarse en Egipto (Ex 16:3), la tierra produciendo lo suficiente para comer hasta hartarse (Lv 25:19; 26:5), y Rut llevandose a casa comida mas alla de su propia saciedad (Rt 2:18). Sin embargo, el Salmo 16:11 eleva la palabra al terreno espiritual: ''en tu presencia hay plenitud de gozo'' (שֹׂבַע שְׂמָחוֹת). El termino abarca una satisfaccion profunda y completa, ya sea del estomago o del alma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7649', 'spa', 'Satisfecho, saciado, lleno — ya sea de comida, favor, años o aflicción; describe plenitud completa o hartazgo', 'Este adjetivo expresa el estado de estar completamente satisfecho o lleno hasta la saciedad. En su uso más positivo, describe a los patriarcas que murieron «llenos de días»: Abraham (Gn 25:8), Isaac (Gn 35:29), David (1 Cr 29:28) y Job (Job 42:17), señalando una vida llevada a su plena realización. Deuteronomio 33:23 bendice a Neftalí como «lleno del favor de Jehová». Sin embargo, la misma palabra tiene un matiz más sombrío: en Job 10:15 y 14:1 uno puede estar «saciado de aflicción» o «harto de deshonra», mientras que Proverbios 27:7 observa que el apetito saciado desprecia hasta la miel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7650', 'spa', 'Jurar o prestar juramento (Nifal); hacer jurar, conjurar o administrar un juramento (Hifil).', 'Enraizado en el número siete — ''hacer siete sobre sí mismo'' era obligarse invocando la plenitud sagrada — este verbo gobierna todo el dominio de la prestación de juramentos en la Biblia hebrea. En su forma Nifal (reflexiva/pasiva), significa jurar, ya sea comprometiéndose a un pacto, afirmando una verdad o invocando maldiciones sobre sí mismo en caso de infidelidad. En su forma Hifil (causativa), significa hacer jurar a otra persona, administrar o imponer un juramento. El siervo de Abraham es ''hecho jurar'' (Gn 24:3), y Josué conjura a Israel en Jericó (Jos 6:26). La conexión etimológica con ''siete'' aflora en el pacto de Abraham en Beerseba, donde siete corderas sellan el juramento (Gn 21:28-31). El español jurar, el francés jurer y el alemán schwören mantienen esta misma flexibilidad de raíz única entre juramentos activos y administrados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7651', 'spa', 'Siete — número cardinal, usado independientemente o en compuestos; raramente como multiplicativo ''siete veces.''', 'El número cardinal siete porta una significación profunda a lo largo del texto bíblico, apareciendo en genealogías, prescripciones rituales, ciclos narrativos y contextos simbólicos. Desde los siete días de la creación hasta la séptuple aspersión de sangre en el ritual levítico, שֶׁבַע impregna la estructura de la Escritura. Las traducciones lo rinden uniformemente con su numeral — inglés seven, español siete, francés sept, alemán sieben — sin ambigüedad alguna en el sentido cardinal básico. Una única aparición en el Salmo 119:164 («Siete veces al día te alabo») usa el número adverbialmente para expresar frecuencia, donde la repetición séptuple insinúa la plenitud que el siete lleva consigo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7652a', 'spa', 'Seba, nombre propio de un rebelde benjaminita contra David y de un gadita en registros genealógicos', 'Un nombre propio hebreo que significa «siete» o «juramento», llevado por al menos dos individuos distintos en el Antiguo Testamento. El más prominente es Seba hijo de Bicri, un benjaminita que encabezó una insurrección contra David tras la revuelta de Absalón, convocando a las tribus del norte con el grito «¡No tenemos parte en David!» (2 S 20:1). Su rebelión fue sofocada cuando la mujer sabia de Abel-bet-maaca dispuso su ejecución. Un segundo Seba aparece en una genealogía gadita (1 Cr 5:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7654', 'spa', 'Saciedad, hartura; estado de satisfacción plena, especialmente con alimento, que a veces conduce al exceso moral.', 'Designa la condición de estar completamente saciado, principalmente de alimento, pero extendiéndose a dimensiones morales y espirituales. La expresión «comer hasta la saciedad» (אָכַל לְשָׂבְעָה) aparece en promesas de abundancia (Isa 23:18; Ezek 39:19) y en invitaciones al verdadero sustento espiritual (Isa 55:2). Sin embargo, la saciedad también puede engendrar complacencia: Ezequiel acusa a Sodoma de una «hartura de pan» que fomentó la arrogancia (Ezek 16:49), y los perros insaciables simbolizan a líderes codiciosos (Isa 56:11). El término abarca tanto la plenitud positiva como la negativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7655', 'spa', 'Siete; numeral cardinal arameo, usado en Daniel y Esdras para períodos y cantidades.', 'Forma aramea del número cardinal siete (שִׁבְעָה), cognado del hebreo שֶׁבַע. Aparece exclusivamente en las secciones arameas de Daniel y Esdras para contar períodos de juicio divino y grupos administrativos. En Daniel, el horno de Nabucodonosor se calienta «siete veces» más de lo normal (Dan 3:19), y «siete tiempos» pasan sobre él durante su locura (Dan 4:16, 23, 25). En Esdras 7:14, el rey persa envía a siete consejeros. Se trata de un numeral directo cuyo uso teológico radica en la simbología de completitud inherente al número siete.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7657', 'spa', 'שִׁבְעִים es el numeral hebreo setenta, plural irregular de שֶׁבַע (siete). Cuenta ancianos (Éx 24:1), años de exilio (Jer 25:11), semanas proféticas ', 'שִׁבְעִים es el numeral hebreo setenta, plural irregular de שֶׁבַע (siete). Cuenta ancianos (Éx 24:1), años de exilio (Jer 25:11), semanas proféticas (Dn 9:24) y descendientes (Gn 46:27). Como otros múltiplos de siete, setenta funciona a menudo como número redondo que implica plenitud o totalidad — los setenta ancianos representan a toda la dirigencia, y las setenta semanas de Daniel abarcan el arco completo de la historia redentora. Las traducciones son uniformes: «setenta», soixante-dix, siebzig, expresando simplemente el numeral sin variación interpretativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7659', 'spa', 'Siete veces, séptuplo; forma dual intensificadora que expresa retribución o bendición completa y amplificada.', 'Forma dual distintiva (שִׁבְעָתַיִם) que significa «siete veces» o «séptuplo», empleada para intensificar promesas y advertencias. La marca protectora de Dios sobre Caín lleva la advertencia de que la venganza será devuelta siete veces (Gen 4:15), y Lamec se jacta de una represalia de setenta y siete veces (Gen 4:24). El salmista ruega que el oprobio de los vecinos sea devuelto siete veces en su regazo (Sal 79:12), mientras que Salmo 12:6 declara las palabras de Dios puras como plata refinada siete veces. Proverbios 6:31 exige al ladrón pagar séptuplo, señalando una restitución total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7662', 'spa', 'Dejar, dejar en paz, permitir que permanezca (arameo); no perturbar algo, dejarlo como está', 'Este verbo arameo significa dejar en paz o permitir que algo permanezca. En la visión del árbol de Daniel, el decreto celestial ordena ''dejar'' el tocón y las raíces en la tierra (Dn 4:15, 23, 26), indicando que el reino de Nabucodonosor se preservaría aunque él mismo fuera humillado. En Esdras 6:7, Darío ordena a los oponentes que ''dejen en paz'' la obra del templo. Daniel 2:44 usa el Hitpeel para describir un reino que ''no será dejado'' a otro pueblo. El español ''dejar/dejad'' confirma el sentido central de permitir que algo continúe sin ser perturbado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7663b', 'spa', 'Esperar, aguardar con esperanza; verbo Piel que expresa confianza paciente dirigida hacia Dios o un resultado anticipado.', 'Un aramaísmo (compárese con el arameo sebar «pensar, esperar» y el siríaco «creer, esperar») usado exclusivamente en la conjugación Piel para expresar una espera paciente y expectante. Las criaturas miran a Dios esperando alimento a su debido tiempo (Sal 104:27; 145:15), mientras que el salmista declara personalmente «he esperado en tus mandamientos» (Sal 119:166). En Ester 9:1, los enemigos «esperaban» dominar a los judíos, pero vieron invertida su expectativa. Rut 1:13 recoge la conmovedora pregunta de Noemí: ¿acaso esperarían sus nueras por hijos aún no nacidos? El español «esperar» abarca admirablemente tanto «aguardar» como «tener esperanza», reflejando el rango semántico del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7665', 'spa', 'Quebrar, destrozar, hacer pedazos; en Nifal: ser quebrado; figuradamente del corazón, el espíritu, el poder y la ruptura del pacto', 'Una de las raíces principales del hebreo para expresar la fractura física violenta: romper cántaros (Jue 7:20), destrozar ídolos (Éx 23:24), quebrar huesos (Éx 12:46). Pero שָׁבַר se extiende con gran fuerza al terreno metafórico. Dios quiebra el yugo de la opresión (Lv 26:13), el cetro altivo de los tiranos (Is 14:5) y el brazo de los malvados (Sal 10:15). Sin embargo, la misma raíz produce una de las imágenes más tiernas de la Escritura: el Dios que está cerca de los «quebrantados de corazón» (נִשְׁבְּרֵי-לֵב, Sal 34:18) y que atesora «un espíritu quebrantado y contrito» (Sal 51:17). Los cognados árabes kasara y etiópico sabara conservan idéntico arco semántico de lo literal a lo figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7666', 'spa', 'Comprar grano o provisiones (Qal); vender grano o distribuir alimentos (Hifil causativo)', 'Comprar grano o provisiones (Qal); vender grano o distribuir alimentos (Hifil causativo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7667', 'spa', 'Quebranto, fractura, brecha; destruccion, ruina; herida, afliccion; interpretacion de un sueno; olas rompientes.', 'Quebranto, fractura, brecha; destruccion, ruina; herida, afliccion; interpretacion de un sueno; olas rompientes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7668', 'spa', 'Grano o cereal como producto alimenticio, especialmente en cuanto mercancía para compra y comercio', 'Sustantivo que designa el grano como mercancía comercial, distinguiéndose de la palabra más general para grano (בָּר) por su énfasis en el intercambio comercial. Casi todas las ocurrencias aparecen en la narrativa de José (Génesis 42-44), donde los hijos de Jacob viajan a Egipto para comprar grano durante la hambruna. La palabra también aparece en Amós 8:5, donde comerciantes deshonestos esperan con impaciencia que termine el sábado para vender grano a precios inflados, y en Nehemías 10:32 respecto al comercio sabático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7673a', 'spa', 'Cesar, desistir, reposar; en Hifil, hacer cesar, poner fin a, quitar o abolir; guardar el reposo sabático.', 'Cesar, desistir, reposar; en Hifil, hacer cesar, poner fin a, quitar o abolir; guardar el reposo sabático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7674', 'spa', 'cesación, reposo, pérdida de tiempo—dejar de trabajar o permanecer inactivo', 'Este sustantivo aparece en contextos que involucran cesación de actividad o pérdida de tiempo productivo. Éxodo 21:19 se refiere a compensación por lesión que causa que alguien pierda trabajo (''su pérdida de tiempo''). Proverbios 20:3 lo asocia con cesar de contienda. El uso en Isaías 30:7 es textualmente incierto pero puede involucrar permanecer quieto o inactividad. La palabra captura el concepto de trabajo detenido o descanso forzado, ya sea por lesión, sabiduría o indolencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7675', 'spa', 'asiento, lugar donde sentarse, morada', 'Este sustantivo, propiamente un infinitivo del verbo «sentarse/habitar», designa un asiento, lugar de habitación o ubicación. Aparece en expresiones que describen la construcción de tronos, tronos metafóricos de violencia, designaciones territoriales y posiblemente la idea de «en el acto». Su origen como infinitivo le confiere gran flexibilidad entre los dominios espaciales y abstractos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7676', 'spa', 'Sábado; el séptimo día de reposo y adoración, aplicado a la observancia semanal, los años sabáticos y como señal del pacto de Dios', 'שַׁבָּת es una de las palabras culturalmente más definitorias de la Biblia hebrea, enraizada en el verbo שָׁבַת («cesar, reposar»). Mucho más que un marcador del calendario, nombra una institución que toca la teología de la creación, la identidad pactual y la esperanza escatológica. El reposo semanal del séptimo día (Éx 20:8-10) es su centro, pero la palabra se extiende al descanso sabático de la tierra (Lv 25:4), a los días solemnes de reposo festivo y a la reivindicación posesiva de Dios sobre la institución: «mis sábados» como señal del pacto (Éx 31:13). La evidencia multilingüe es notablemente uniforme: español sábado, francés sabbat y alemán Sabbat transliteran en vez de traducir, reflejando el peso cultural irreductible de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7677', 'spa', 'Reposo solemne o sabbatismo, cesación completa del trabajo divinamente ordenada para ocasiones sagradas', 'Una forma intensificada relacionada con ''sábado'', que denota no simplemente un día libre sino un descanso completo y sagrado dispuesto por Dios. Aparece por primera vez cuando se indica a Israel que el séptimo día será un shabbatón de santo reposo para el SEÑOR (Éx 16:23), incluso antes de la legislación formal del Sinaí. El término se aplica al sábado semanal (Éx 31:15; 35:2), al Día de la Expiación (Lv 16:31; 23:32), al primer y séptimo día de los Tabernáculos (Lv 23:39) y al año sabático cuando la tierra misma reposa (Lv 25:4-5). Conlleva un matiz de plenitud solemne que el simple ''descanso'' no alcanza a captar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7678', 'spa', 'Sabetai—nombre de un levita en la comunidad postexílica', 'Este nombre personal identifica a un levita que aparece en tres contextos postexílicos: oponiéndose a la investigación de Esdras sobre matrimonios extranjeros (Esdras 10:15), ayudando a explicar la Ley (Nehemías 8:7), y sirviendo en supervisión del templo (Nehemías 11:16). El nombre probablemente deriva de ''sábado'', sugiriendo que el portador nació en o estaba asociado con ese día. El mismo individuo puede aparecer en los tres pasajes, mostrando continuidad en el liderazgo levítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7680', 'spa', 'crecer, aumentar—multiplicarse o hacerse abundante (arameo)', 'Este verbo arameo significa crecer, aumentar o multiplicarse. Aparece en correspondencia oficial del período persa (Esdras 4:22) advirtiendo contra que el daño aumente al imperio, y en saludos reales deseando que la paz se multiplique (Daniel 4:1, 6:25). El término transmite expansión o aumento, ya sea de daño o bendición, y refleja el lenguaje administrativo arameo usado en estos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7682', 'spa', 'Ser inaccesiblemente alto; poner en alto para protección; ser exaltado en estatus u honor (Qal, Nifal, Piel, Hifil, Pual)', 'Ser inaccesiblemente alto; poner en alto para protección; ser exaltado en estatus u honor (Qal, Nifal, Piel, Hifil, Pual)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7683', 'spa', 'extraviarse, errar, pecar involuntariamente', 'Este verbo denota extraviarse o pecar de manera inadvertida, sin intención deliberada. Es fundamental en el sistema sacrificial de Israel, donde distingue los pecados por ignorancia de la rebeldía premeditada. La legislación sacerdotal provee expiación para tales errores, reconociendo la falibilidad humana sin renunciar a la responsabilidad moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7684', 'spa', 'Error, inadvertencia — un pecado no intencional a diferencia de la transgresión deliberada', 'Error, inadvertencia — un pecado no intencional a diferencia de la transgresión deliberada');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7686', 'spa', 'Extraviarse, errar o vagar; en Hifil, hacer errar; por extensión, embriagarse o extasiarse', 'Extraviarse, errar o vagar; en Hifil, hacer errar; por extensión, embriagarse o extasiarse');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7687', 'spa', 'Segub (nombre propio, ''exaltado, protegido'')', 'Este nombre masculino, que significa «exaltado» o «protegido», identifica a dos individuos: el hijo menor de Hiel, quien murió cuando se colocaron las puertas de Jericó (cumpliendo la maldición de Josué), y un descendiente de Judá por la línea de Hezrón. El nombre refleja patrones hebreos comunes de denominación que invocan elevación o protección divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7688', 'spa', 'contemplar, mirar atentamente—observar o considerar con atención enfocada', 'Este verbo Hiphil describe el acto de contemplar o mirar cuidadosamente algo. El Salmo 33:14 representa a Dios observando desde el cielo a la humanidad. Cantares 2:9 retrata al amado asomándose por las ventanas. Isaías 14:16 describe a los observadores mirando con asombro al rey caído de Babilonia. El término sugiere más que una mirada casual—implica observación enfocada, a menudo prolongada, ya sea vigilancia divina o escrutinio humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7690', 'spa', 'Adjetivo arameo: grande (en tamaño/importancia); abundante, mucho, muchos (cantidad); sumamente (uso adverbial). Aparece exclusivamente en Daniel y Es', 'Adjetivo arameo: grande (en tamaño/importancia); abundante, mucho, muchos (cantidad); sumamente (uso adverbial). Aparece exclusivamente en Daniel y Esdras, abarcando la grandeza de tamaño, la abundancia cuantitativa y la intensidad adverbial. La colosal estatua de Nabucodonosor era ''grande'' en esplendor (Dan 2:31), y el árbol cósmico daba fruto ''abundante'' para todos (Dan 4:12, 21). En su uso adverbial funciona como intensificador: el rey estaba ''sumamente'' airado (Dan 2:12), Belsasar ''grandemente'' alarmado (Dan 5:9), y el espíritu de Daniel ''profundamente'' turbado (Dan 7:28). Las correspondencias en español muy/mucho y en alemán viel/sehr muestran cómo los sentidos cuantitativo e intensivo se entrelazan naturalmente entre lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7693', 'spa', 'violar, forzar sexualmente', 'Este verbo denota violación sexual. Los masoretas lo consideraron obsceno y sustituyeron el eufemismo «acostarse con» en su tradición de lectura (Qeré), preservando el texto original (Ketiv). El término aparece en maldiciones, juicios proféticos y acusaciones, siempre describiendo agresión sexual violenta. La sensibilidad de los escribas refleja la gravedad del crimen descrito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7695', 'spa', 'consortes reales, esposas—concubinas o esposas secundarias de reyes persas (arameo)', 'Este sustantivo arameo se refiere a consortes reales o esposas, apareciendo exclusivamente en Daniel 5 durante el banquete de Belsasar. El término distingue a estas mujeres de las reinas principales, probablemente refiriéndose a esposas secundarias o concubinas del harén real persa. El acto de Belsasar de traerlas para beber de los vasos del templo de Jerusalén (Daniel 5:2-3, 23) agrava el sacrilegio, mostrando desprecio por los objetos sagrados al usarlos en una fiesta real disoluta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7696', 'spa', 'שָׁגַע — estar loco, actuar dementemente; locura tanto genuina como fingida, incluyendo frenesí profetico.', 'Verbo cuyo participio Pual מְשֻׁגָּע se ha convertido en una de las palabras culturalmente mas perdurables del hebreo. Describe el estado de estar enloquecido o comportarse como un demente, abarcando un espectro que va desde la maldicion pactual de la insania (Dt 28:34), pasando por la locura fingida de David ante Aquis de Gat (1 S 21:14-16), hasta el desprecio con que se tachaba a los profetas de locos (Os 9:7; Jer 29:26; 2 R 9:11). La raiz Hitpael añade el matiz de hacerse deliberadamente el loco, como en la estratagema de David. Cognados arabes relacionan el termino con el arrullo de palomas y los gemidos de camellos, sugiriendo una vocalizacion frenetica e incontrolada como imagen nuclear.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7697', 'spa', 'locura, demencia—trastorno mental violento o comportamiento frenético', 'Este sustantivo describe locura o demencia, ya sea trastorno mental literal o el comportamiento salvaje y frenético que se le asemeja. Deuteronomio 28:28 amenaza con juicio incluyendo locura junto con ceguera y confusión. Zacarías 12:4 habla de Dios hiriendo caballos con locura en batalla. Segundo de Reyes 9:20 describe el manejo de Jehú como ''semejante a la locura''—temerariamente, furiosamente. El término captura tanto demencia clínica como descripciones hiperbólicas de comportamiento frenético e incontrolado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7698', 'spa', 'Cría, crías del ganado; la prole o descendencia de los animales domésticos', 'שֶׁגֶר designa la cría o prole de los animales domésticos, y siempre aparece en constructo con ganado o bestias. En Éxodo 13:12 se refiere a la primera cría del ganado que debe consagrarse al SEÑOR. Deuteronomio empareja repetidamente ''la cría de tus vacas'' con ''las crías de tus ovejas'' en el contexto de bendiciones y maldiciones del pacto (Dt 7:13; 28:4, 18, 51). El español ''cría de'' capta con naturalidad el sentido de progenie animal como señal de bendición agrícola divina o de su eliminación bajo la maldición pactual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7699a', 'spa', 'Pecho femenino; usado literalmente para la lactancia y figuradamente para la belleza, la intimidad y la personificación nacional', 'Pecho femenino; usado literalmente para la lactancia y figuradamente para la belleza, la intimidad y la personificación nacional');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7699b', 'spa', 'pecho—el seno femenino, fuente literal o figurada de sustento', 'Este sustantivo denota el pecho, particularmente como fuente de leche y crianza. Job 24:9 menciona arrebatar niños del pecho en contextos de opresión. Isaías lo usa figuradamente: 60:16 habla de mamar del pecho de reyes (recibir su riqueza), mientras 66:11 describe mamar del pecho consolador de Jerusalén. La imagen enfatiza provisión y consuelo maternal, ya sea lactancia literal o sustento metafórico de fuentes poderosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7701', 'spa', 'Destrucción, devastación; violencia, despojo; ruina causada por fuerza hostil', 'Destrucción, devastación; violencia, despojo; ruina causada por fuerza hostil');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7702', 'spa', 'rastrillar, desmenuzar la tierra—cultivar o labrar la tierra rompiendo terrones', 'Este verbo Piel describe el rastrillado, el proceso agrícola de romper la tierra arada para prepararla para la siembra. Isaías 28:24 lo usa en una pregunta retórica sobre agricultura—¿acaso el labrador rastrilla continuamente sin plantar? Oseas 10:11 lo emplea figuradamente para la tarea de Judá bajo disciplina divina. Job 39:10 pregunta si el buey salvaje puede ser hecho rastrillar los valles. El término captura el rompimiento y alisado sistemático de la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7703', 'spa', 'Tratar con violencia, despojar, devastar, arruinar; como participio: destructor, saqueador; en pasiva: ser asolado.', 'Tratar con violencia, despojar, devastar, arruinar; como participio: destructor, saqueador; en pasiva: ser asolado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7704a', 'spa', 'Campo, terreno abierto; forma poética de שָׂדֶה que designa tierra cultivada, terreno silvestre o tierra en sentido amplio. Es una forma rara, arcaica', 'Campo, terreno abierto; forma poética de שָׂדֶה que designa tierra cultivada, terreno silvestre o tierra en sentido amplio. Es una forma rara, arcaica y exclusivamente poética del sustantivo común שָׂדֶה (''campo''). Aparece en contextos elevados: el cántico de Moisés celebra la miel de la roca y el aceite del campo pedregoso (Dt 32:13), los salmistas alaban todo lo que el campo contiene (Sal 96:12), y los profetas la usan para tierra cultivada (Os 10:4) y campo abierto donde vagan las bestias salvajes (Is 56:9; Sal 50:11; 80:14; 104:11). El francés a veces la confunde con שַׁדַּי (''Todopoderoso'') por tener consonantes idénticas, pero el español campo y el alemán Feld identifican correctamente el sentido agrícola y geográfico. Jeremías 4:17 la emplea memorablemente: ''como guardas de un campo la rodean.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7704b', 'spa', 'Campo, tierra cultivada; también campo abierto o terreno silvestre, en contraste con parcelas agrícolas trabajadas', 'La palabra básica para designar una parcela de tierra agrícola en la Biblia hebrea, שָׂדֶה aparece desde el principio mismo del relato: Dios aún no había hecho llover sobre «el campo» (Gn 2:5). Abarca desde el campo de cebada de Booz en Rut hasta el terreno que Jeremías compra como señal de esperanza (Jer 32). En estado constructo con topónimos designa una región más amplia: «el campo de Moab», «el campo de Zoán» (Sal 78:12). Un caso limítrofe interesante aparece en 2 Reyes 4:39, donde «campo» califica plantas silvestres —calabazas recogidas del שָׂדֶה—, aludiendo a campo abierto no cultivado. El español campo y el francés champ conservan exactamente esta misma ambigüedad entre «parcela» y «campiña».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7706', 'spa', 'Shaddai — el Todopoderoso; nombre o epíteto divino para Dios, especialmente en las promesas patriarcales y el libro de Job.', 'Shaddai — el Todopoderoso; nombre o epíteto divino para Dios, especialmente en las promesas patriarcales y el libro de Job.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7707', 'spa', 'Sedeur; rubenita, padre de Elisur, cuyo nombre significa ''el Todopoderoso es llama/luz''', 'Sedeur es un nombre propio masculino portado por el padre de Elisur, jefe de la tribu de Ruben durante el periodo del desierto. El nombre probablemente combina שַׁדַּי (''el Todopoderoso'') con אוּר (''llama'' o ''luz''), con el significado de ''el Todopoderoso es mi luz''. Las cinco apariciones se encuentran en Numeros dentro de listas sacerdotales de censos y ofrendas (Num 1:5; 2:10; 7:30, 35; 10:18). La LXX lo transcribe como Σεδιουρ, y las traducciones en distintas lenguas lo transliteran de manera uniforme, confirmando su condicion de nombre personal fijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7708', 'spa', 'Sidim—el valle donde estaban las ciudades del Mar Muerto, posteriormente sumergido', 'Este nombre de lugar identifica el valle donde se ubicaban Sodoma, Gomorra y las ciudades aliadas antes de su destrucción. Génesis 14:3, 8, 10 localiza la batalla de los reyes en este valle, posteriormente identificado con el Mar Salado (Mar Muerto). El nombre puede relacionarse con ''campos'' o ''surcos'', aunque las interpretaciones varían. Para cuando se escribió Génesis, este valle antes habitado se había convertido en la cuenca del Mar Muerto, preservando una memoria geográfica del paisaje pre-catastrófico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7709', 'spa', 'Campo, terreno cultivado; se usa para tierras agrícolas en terrazas en descripciones poéticas y proféticas de fertilidad o devastación.', 'Sustantivo femenino que aparece solo en plural, designando campos cultivados o tierras agrícolas en terrazas. En Deuteronomio 32:32 describe los viñedos de Sodoma, mientras que Isaías 16:8 lamenta los célebres campos de Hesbón. Habacuc 3:17 lo empareja con el fracaso de la higuera y la vid, pintando un cuadro de colapso agrícola total. La palabra conlleva un sentido de terreno cuidadosamente labrado, tierra moldeada por el trabajo humano, lo cual hace su destrucción aún más conmovedora en los oráculos proféticos de juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7710', 'spa', 'quemado, arruinado por el viento del este—grano dañado por los vientos calientes del siroco', 'Este participio pasivo Qal describe grano que ha sido quemado o arruinado por el viento del este, el siroco caliente que podía devastar las cosechas. Las tres apariciones están en Génesis 41, en el sueño del Faraón de las siete espigas quemadas que devoraron las saludables. El término describe vívidamente el desastre agrícola, ya que el viento del este proveniente del desierto podía marchitar el grano en la espiga, representando los siete años de hambruna que José posteriormente interpretaría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7711b', 'spa', 'tizon, anublo; enfermedad de los cultivos que marchita y ennegrece el grano antes de la cosecha', 'שִׁדָּפוֹן designa el tizon o anublo, una devastadora enfermedad fungica que ataca el grano en el campo, siempre mencionada junto con יֵרָקוֹן (moho o amarillez). Aparece en maldiciones del pacto (Dt 28:22) y en descripciones del juicio agricola divino (Am 4:9; Hag 2:17). La oracion de Salomon en la dedicacion del templo la incluye entre las calamidades nacionales que requieren intercesion (1 R 8:37; 2 Cr 6:28). El termino evoca la destruccion abrasadora que esta plaga inflige sobre el grano en pie.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7713', 'spa', 'Filas, hileras (de soldados en formación o vigas en construcción arquitectónica)', 'Este sustantivo designa filas o hileras, ya sea de soldados en formación de batalla o, en un contexto arquitectónico poco claro, de vigas o tablones en una construcción. El término aparece en contextos militares que describen formaciones protectoras y en la descripción del templo de Salomón, donde su significado preciso sigue siendo incierto. La raíz sugiere la idea de disposición u ordenamiento en líneas regulares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7715', 'spa', 'Sadrac; el nombre babilónico dado a Hananías, uno de los tres compañeros de Daniel en el horno de fuego. Nombre de la corte babilónica asignado a Hana', 'Sadrac; el nombre babilónico dado a Hananías, uno de los tres compañeros de Daniel en el horno de fuego. Nombre de la corte babilónica asignado a Hananías, uno de los cuatro jóvenes judíos deportados a Babilonia y formados en la sabiduría caldea (Dan 1:7). Sadrac aparece junto a Mesac y Abed-nego a lo largo de Daniel 3, donde los tres se niegan a adorar la imagen de oro de Nabucodonosor y son arrojados a un horno de fuego, del cual salen ilesos, lo que lleva al rey a decretar honra a su Dios. Daniel 2:49 señala que Sadrac fue puesto sobre los asuntos de la provincia de Babilonia a petición de Daniel. La etimología del nombre sigue siendo debatida; algunos lo relacionan con Shudur-Aku (''mandato de Aku,'' una deidad lunar), aunque esto es incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7716', 'spa', 'Una cabeza de ganado menor (oveja o cabra) del rebano; frecuentemente un cordero en contextos sacrificiales y figurados.', 'Una cabeza de ganado menor (oveja o cabra) del rebano; frecuentemente un cordero en contextos sacrificiales y figurados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7718', 'spa', 'Ónice o piedra preciosa bandeada, usada en las vestiduras del sumo sacerdote y entre los tesoros del Edén', 'Una gema preciada que aparece en algunos de los escenarios con mayor carga simbólica de las Escrituras. Se encuentra entre los tesoros del Edén en la tierra de Havila (Gn 2:12), se prescribe para las hombreras del efod donde se graban los nombres de las doce tribus de Israel (Éx 25:7; 28:9, 20), y figura entre las ofrendas que David reunió para el templo (1 Cr 29:2). Job declara que el valor de la sabiduría supera al oro y a la piedra de שֹׁהַם (Job 28:16). La identificación mineralógica exacta sigue siendo debatida — las versiones antiguas varían entre ónice, berilo y sardónice — pero el contexto constante es de belleza, rareza y propósito sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7720', 'spa', 'medias lunas, ornamentos lunares—joyas o piezas decorativas en forma de media luna', 'Este sustantivo plural se refiere a ornamentos en forma de media luna, probablemente joyas modeladas según la forma curva de la luna. Aparecen como decoraciones en camellos (Jueces 8:21, 26) y como adornos femeninos en el catálogo de artículos de lujo de Isaías (3:18). Estas piezas con forma de luna pueden haber tenido funciones apotropaicas o decorativas, comunes en culturas del antiguo Cercano Oriente donde los símbolos lunares tenían significado. El término revela tanto el atractivo estético como las posibles asociaciones religiosas de la imaginería de la media luna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7722b', 'spa', 'Devastación, ruina; desolación causada por juicio o calamidad; tempestad violenta en sentido figurado', 'El sustantivo שׁוֹאָה (también escrito שֹׁאָה) designa una destrucción catastrófica — el tipo de ruina que deja un lugar desolado o a una persona completamente arruinada. Describe el juicio divino que se abate sobre los malvados (Sal 35:8; Pr 3:25), la devastación repentina de Babilonia (Is 47:11) y el páramo que Job recorre (Job 30:3, 14). En dos vívidas comparaciones adopta la forma específica de tempestad: Proverbios 1:27 advierte que la calamidad vendrá ''como tempestad'' (כְּשׁוֹאָה), y Ezequiel 38:9 describe a Gog ascendiendo ''como tempestad''. El español capta ambos registros con ''destrucción/desolación'' para la ruina y ''tempestad/tormenta'' para la imagen de la tormenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7723', 'spa', 'Vacuidad, vanidad; inutilidad, futilidad; falsedad, engaño; como adverbio: en vano, sin propósito.', 'Vacuidad, vanidad; inutilidad, futilidad; falsedad, engaño; como adverbio: en vano, sin propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7725', 'spa', 'Volver, regresar; (Hifil) hacer volver, restaurar, responder, retribuir; (Polel) restaurar plenamente; apartarse, apostatar', 'Uno de los verbos con mayor carga teológica de la Biblia Hebrea, שׁוּב abarca el retorno físico a un lugar, el arrepentimiento espiritual (volver a Dios) y el acto causativo de restauración. Su tema Hifil se ramifica en hacer volver cautivos, responder una palabra y retribuir acciones. Los profetas se apoderaron de su doble sentido: el mismo verbo que describe regresar del exilio describe el retorno al Señor. En español ''volver'' y en francés retourner reflejan esa doble fuerza, mientras que el alemán umkehren capta el sentido dramático de reversión que hace de שׁוּב la palabra bíblica por excelencia del arrepentimiento y la renovación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7726', 'spa', 'Apóstata, rebelde, que se aparta de Dios; describe a quien vuelve la espalda a la fe', 'Este adjetivo caracteriza a quien se aparta de Dios, un apóstata o rebelde. Posiblemente derivado de una forma participial intensiva, capta la acción de volverse atrás o rebelarse contra la relación pactual. El término aparece en llamados proféticos al arrepentimiento y en condenaciones de rebelión persistente, enfatizando el abandono deliberado de la alianza con Dios. Contiene un juego de palabras con la raíz שׁוּב, que significa tanto «volver» como «apartarse».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7727', 'spa', 'Sobab (nombre propio masculino, posiblemente «rebelde» o «que se aparta»)', 'Este nombre propio masculino, cuya etimología posiblemente significa «rebelde» o «que se aparta», identifica a dos individuos bíblicos: un hijo de David nacido en Jerusalén y un hijo de Caleb. El nombre aparece en varias listas genealógicas. A pesar de su etimología potencialmente negativa, funcionaba como nombre personal corriente sin estigma aparente, algo frecuente en la onomástica del antiguo Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7728', 'spa', 'apóstata, infiel, desleal—quien se aparta de la lealtad del pacto', 'Este adjetivo describe a alguien caracterizado por la apostasía o infidelidad, apartándose de la fidelidad. Jeremías lo usa para Israel como ''la hija infiel'' (31:22) y para Amón como ''la hija apóstata'' (49:4). El uso en Miqueas 2:4 es textualmente difícil pero puede referirse a apóstatas o captores. El término captura no un lapso momentáneo sino una infidelidad establecida, un dar la espalda a compromisos previos o a la relación del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7732', 'spa', 'Sobal, nombre propio de un jefe de clan edomita (horita) y de figuras en las genealogías de Judá y Caleb', 'Nombre propio que aparece tanto en genealogías edomitas como judaítas. La primera mención identifica a Sobal como hijo de Seir el horita y uno de los jefes de clan de Edom (Gn 36:20, 23, 29), con un listado paralelo en 1 Crónicas 1:38, 40. Un segundo Sobal aparece como descendiente de Caleb y fundador de Quiriat-jearim (1 Cr 2:50, 52), y un tercero en el linaje de Judá (1 Cr 4:1-2). La LXX transcribe el nombre como Σουβαλ. La coincidencia entre genealogías edomitas y judaítas puede reflejar migraciones históricas de clanes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7737a', 'spa', 'Ser igual, comparable o de valor equivalente; también nivelar, alisar, asemejar o colocar deliberadamente. Construido sobre la idea raíz de uniformida', 'Ser igual, comparable o de valor equivalente; también nivelar, alisar, asemejar o colocar deliberadamente. Construido sobre la idea raíz de uniformidad y lisura, שָׁוָה abarca desde la nivelación concreta del terreno (Is 28:25) hasta la retórica teológica más elevada: ''¿A quién me haréis semejante, para que sea igual?'' (Is 46:5). En Ester, la palabra toma un giro pragmático: Amán calcula que la destrucción de los judíos ''conviene'' al rey (3:8), mientras que Ester protesta que el daño del enemigo no ''iguala'' la pérdida del rey (7:4). El Salmo de confianza serena (131:2) usa el Piel para aquietar el alma, una hermosa extensión metafórica de la nivelación física a la calma interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7737b', 'spa', 'Poner, colocar o posicionar deliberadamente; tambien nivelar o afianzar (Piel de שָׁוָה II).', 'Verbo en Piel que significa poner o colocar algo con intencion deliberada, y por extension nivelar o dar pie seguro. En el Salmo 16:8 el salmista declara ''A YHWH he puesto siempre delante de mi'', mientras que en el Salmo 89:19 Dios coloca fuerza sobre un guerrero escogido. La forma participial en 2 Samuel 22:34 evoca la vivida imagen de Dios haciendo los pies del adorador tan agiles como los de una cierva en las alturas. El verbo abarca desde la compostura interior hasta el posicionamiento deliberado de algo o alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7743', 'spa', 'Hundirse, abatirse; descender hacia el suelo o la muerte, frecuentemente en contextos de humillación o mortalidad', 'Este verbo describe un movimiento descendente de hundirse o abatirse, ya sea en sentido físico o metafórico. En el Salmo 44:25, el alma se hunde hasta el polvo en humillación. Proverbios 2:18 lo emplea para la casa de la adúltera que desciende hacia la muerte, imagen vívida de decadencia moral. La palabra capta el movimiento inexorable hacia la tierra o el Seol, ya sea en adoración, derrota o colapso moral. Su uso escaso (4 veces) sugiere una forma poética e intensiva reservada para momentos de gran dramatismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7745', 'spa', 'fosa; hoyo en el suelo, literal o figurado para traicion y peligro moral', 'שׁוּחָה designa una fosa u hoyo en el suelo, empleada tanto en sentido literal como figurado. Jeremias 2:6 describe el desierto como tierra de sequedad y fosas, evocando un terreno desolado. En Jeremias 18:20 y 18:22, los enemigos ''cavan una fosa'' para el profeta, metafora de conspiracion traicionera. Proverbios la utiliza en sentido figurado para el peligro moral: la boca de la mujer ajena es una ''fosa profunda'' en la que caen los que el Senor rechaza (Pr 22:14; 23:27). El sentido concreto de excavacion subyace en todas las metaforas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7747', 'spa', 'suhita; gentilicio para un descendiente de Sua, aplicado exclusivamente a Bildad en Job', 'Adjetivo gentilicio que identifica a alguien como descendiente de Sua, uno de los hijos de Abraham con Cetura (Gn 25:2). En las Escrituras aparece unicamente como epiteto de Bildad, uno de los tres amigos de Job. La LXX lo transcribe como Σαυχίτης. Bildad el suhita interviene en tres ciclos de dialogo (Job 8, 18, 25), sosteniendo de manera constante que el sufrimiento es resultado del pecado y que la justicia de Dios es inflexible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7751a', 'spa', 'Ir de un lado a otro, vagar, recorrer; del deambular inquieto, la búsqueda y el errar sin rumbo', 'Verbo de movimiento que abarca desde el recorrido con propósito hasta el vagabundeo sin dirección. En su forma básica Qal describe al pueblo yendo a recoger el maná (Nm 11:8) y a Satanás vagando por la tierra (Job 1:7). La intensificación Polel transforma este movimiento en un recorrido ávido y decidido: los ojos del SEÑOR recorren toda la tierra (2 Cr 16:9), o las personas buscan desesperadamente la palabra de Dios (Am 8:12). El único Hitpael en Jeremías 49:3 añade una nota de huida frenética e inquieta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7752', 'spa', 'Látigo o azote, usado literalmente para el castigo y figuradamente para el juicio divino y la calamidad', 'Designa el instrumento para golpear: un látigo, fusta o azote, empleado en contextos tanto de crueldad humana como de disciplina divina. La infame amenaza de Roboam de castigar a Israel con escorpiones en lugar de los azotes de su padre marca la ruptura política del reino (1 R 12:11, 14). El amigo de Job, Elifaz, habla de estar oculto del ''azote de la lengua'' (Job 5:21), extendiendo la imagen al ataque verbal. Isaías presenta al SEÑOR blandiendo un azote contra Asiria como cuando golpeó a Egipto junto al mar (Is 10:26; 28:15, 18). La palabra así tiende un puente entre el castigo físico y el juicio cósmico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7755', 'spa', 'Soco (tambien Socoh, Socó), toponimo en Juda que aparece tanto en la Sefela como en la region montañosa.', 'Sustantivo propio femenino que designa al menos dos ciudades en el territorio de Juda, ambas llamadas Soco (con variantes ortograficas Socoh, Socó). La mas conocida, situada en la Sefela, es el lugar donde los filisteos acamparon antes del celebre enfrentamiento de David con Goliat (1 S 17:1), y aparece luego como una de las ciudades fortificadas por Roboam (2 Cr 11:7) y entre las conquistadas por los filisteos (2 Cr 28:18). Una segunda Soco se ubica en la zona montañosa de Juda, cerca de Hebron (Jos 15:48; 1 Cr 4:18). Su identificacion moderna corresponde a Khirbet esh-Shuweikeh.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7757', 'spa', 'Dobladillo, falda o cola de una vestidura; usado para vestimentas sacerdotales, la visión divina y metáforas de vergüenza', 'Se refiere al borde inferior o la falda ondulante de una túnica, siempre en forma plural. En las instrucciones del tabernáculo, campanillas de oro y granadas se cuelgan de los bordes del manto del efod del sumo sacerdote (Ex 28:33-34; 39:24-26), donde anuncian sus movimientos en la presencia de Dios. Isaías contempla al Señor sentado en un trono, y sus faldas llenan el templo (Is 6:1), una visión de majestad abrumadora. Los profetas luego invierten la imagen: Jeremías y Nahúm hablan de faldas levantadas y expuestas como figura de humillación nacional y juicio (Jer 13:22, 26; Nah 3:5), y Lamentaciones halla la sangre de inocentes en las faldas de Jerusalén (Lm 1:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7758', 'spa', 'Descalzo, despojado de calzado; adjetivo adverbial que indica el estado de ir sin zapatos, a menudo en contextos de humillación o juicio', 'Este adjetivo aparece exclusivamente junto al verbo «caminar», describiendo a alguien que va descalzo. En Miqueas 1:8, el profeta declara que caminará descalzo y desnudo como señal de duelo y juicio. Job 12:17 y 12:19 describen a Dios conduciendo descalzos a consejeros y sacerdotes, despojándolos de su dignidad. En el mundo antiguo, caminar descalzo señalaba vergüenza, duelo, cautividad o simbolismo profético: una remoción de la dignidad social ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7760a', 'spa', 'Poner, colocar, situar; convertir en; designar; poner el corazón/la atención en; dar, otorgar', 'Esta raíz expresa el acto de poner o colocar algo en un lugar, tanto física como metafóricamente. Va desde la colocación literal —Abraham poniendo la leña sobre los hombros de Isaac, los hermanos de José depositándolo en la cisterna— hasta usos transformativos donde Dios convierte una cosa en otra (granos de arena, una nación fecunda). El verbo también cubre el nombramiento de funcionarios, la dirección del corazón o la atención hacia algo, y el otorgamiento de nombres o bendiciones. El español poner, el francés mettre y el alemán setzen se corresponden estrechamente a través de estas acepciones, mientras que los traductores coreanos distinguen el sentido transformativo (만들다, «hacer») de la mera colocación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7760b', 'spa', 'poner, colocar, designado—el acto de poner o establecer algo', 'Este término aparece en contextos de poner o colocar, aunque su fuerza exacta se debate. Segunda de Samuel 13:32 puede involucrar algo ''puesto'' o predeterminado, mientras que Isaías 10:6 (apareciendo dos veces) habla de poner o designar algo como pisoteado. El rango semántico involucra colocación o designación intencional, ya sea de planes, objetos o personas. Dificultades textuales en algunos pasajes hacen incierto el significado preciso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7761', 'spa', 'Poner, colocar o establecer; emitir un decreto; designar a alguien en un cargo. Cognado arameo del hebreo שׂוּם/שִׂים', 'Poner, colocar o establecer; emitir un decreto; designar a alguien en un cargo. Cognado arameo del hebreo שׂוּם/שִׂים');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7766', 'spa', 'Sunem—ciudad en Isacar, hogar de Abisag y la sunamita', 'Este nombre de lugar identifica una ciudad en el territorio de Isacar, la moderna Sûlem al norte de Jezreel. Josué 19:18 la enumera entre las heredades de Isacar. Primera de Samuel 28:4 ubica allí el campamento filisteo antes de la batalla final de Saúl. Segunda de Reyes 4:8 presenta a la mujer prominente de Sunem que hospedó a Eliseo. La ciudad aparece así en narrativas diversas: asignación tribal, guerra real y ministerio profético, conservando siempre su identidad geográfica en el área del valle de Jezreel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7767', 'spa', 'La sunamita, adjetivo gentilicio que identifica a una mujer procedente de la ciudad de Sunem.', 'Adjetivo gentilicio femenino que designa a una mujer de Sunem, ciudad en el territorio de Isacar. El termino identifica a dos mujeres notables en la Biblia. La primera es Abisag la sunamita, la hermosa joven llevada para atender al anciano rey David (1 R 1:3, 15), cuya condicion se convirtio luego en un punto de conflicto politico cuando Adonias la pidio por esposa (1 R 2:17, 21-22). La segunda es la anonima ''mujer notable'' de Sunem en el ministerio de Eliseo, quien hospedaba al profeta y cuyo hijo fue resucitado de entre los muertos (2 R 4:12, 25, 36).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7768', 'spa', 'Clamar por ayuda, suplicar o llamar urgentemente a Dios en angustia (Piel de שׁוע)', 'Clamar por ayuda, suplicar o llamar urgentemente a Dios en angustia (Piel de שׁוע)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7775', 'spa', 'Clamor de auxilio o grito de angustia, dirigido a Dios en lamento y surgido de la opresión', 'Sustantivo femenino que expresa la súplica cruda y angustiada de quien está desesperado, ya sea un individuo en los Salmos o un pueblo entero en cautiverio. El clamor (shav''ah) de Israel asciende desde la esclavitud en Egipto y llega a los oídos de Dios (Ex 2:23). David, huyendo por su vida, declara que su clamor llegó ante Dios y entró en sus oídos (2 S 22:7; Sal 18:6). A lo largo del Salterio, esta palabra aparece en algunas de las súplicas más íntimas de atención divina: ''llegue mi clamor delante de ti'' (Sal 102:1), ''no desprecia el clamor de los afligidos'' (Sal 34:15). Es el vocabulario del último recurso, la voz de quienes no tienen a quién más acudir.');